/**
 * ۳۴. بادبادک‌باز — خالد حسینی
 * ۷ فصل | هر فصل ۴۰ پاراگراف طولانی
 */
object Story34 {

    fun get(): StoryContent = StoryContent(
        storyId = "adv_kite_runner",
        chapters = listOf(
            chapter1(), chapter2(), chapter3(), chapter4(),
            chapter5(), chapter6(), chapter7(),
        )
    )

    // ─────────── فصل ۱: کابل، ۱۹۷۵ ───────────
    private fun chapter1() = StoryChapter(
        number = 1, title = "Kabul, 1975", titlePersian = "کابل، ۱۹۷۵",
        paragraphs = listOf(
            StoryParagraph("I became what I am today at the age of twelve, on a frigid overcast day in the winter of 1975, and I remember the precise moment with a clarity that has never faded, because that was the day my past clawed its way out of the dark and into the light of memory, where it has remained ever since, waiting, watching, refusing to be buried.", "آنچه امروز هستم را در دوازده‌سالگی شدم، در روزی سرد و ابری در زمستان ۱۹۷۵ و آن لحظه دقیق را با وضوحی به یاد می‌آورم که هرگز محو نشده، چون آن روزی بود که گذشته‌ام راه خود را از تاریکی بیرون کشید و به روشنایی خاطره آمد، جایی که از آن زمان مانده است، منتظر، تماشاکنان، امتناع‌کنان از دفن شدن."),
            StoryParagraph("I remember the day well, and yet, in a strange way, I also remember standing in a stranger's kitchen and learning that the past is never truly past, that it cannot be buried, that it always finds a way to return, that it waits for us at the most unexpected moments, in the most unexpected places, demanding to be faced.", "روز را خوب به یاد می‌آورم و با این حال، به شیوه‌ای عجیب، همچنین به یاد می‌آورم در آشپزخانه غریبه‌ای ایستاده بودم و آموختم گذشته هرگز واقعاً گذشته نیست، نمی‌شود دفنش کرد، همیشه راهی برای بازگشت پیدا می‌کند، در غیرمنتظره‌ترین لحظه‌ها، در غیرمنتظره‌ترین جاها منتظرمان می‌ماند، می‌خواهد با آن روبرو شویم."),
            StoryParagraph("The telephone rang in my home in San Francisco, in the winter of 2001, and a voice from twenty-six years ago spoke to me, and I knew, before he said anything of consequence, that the call would change everything, that it would pull me back into a past I had spent decades trying to forget.", "تلفن در خانه‌ام در سانفرانسیسکو، در زمستان ۲۰۰۱ زنگ خورد و صدایی از بیست‌وشش سال پیش با من صحبت کرد و می‌دانستم، پیش از آنکه چیزی با اهمیت بگوید، که آن تماس همه چیز را تغییر می‌دهد، که مرا به گذشته‌ای بازمی‌کشد که دهه‌ها تلاش کرده بودم فراموشش کنم."),
            StoryParagraph("'There is a way to be good again,' Rahim Khan said, and those six words, spoken in a voice I had known since childhood, in a tone that was neither accusation nor absolution, undid me completely, because they offered the one thing I had never allowed myself to hope for: the possibility of forgiveness.", "رحیم‌خان گفت: «راهی برای دوباره خوب بودن هست،» و آن شش کلمه، گفته‌شده با صدایی که از کودکی می‌شناختم، با لحنی که نه اتهام بود و نه بخشش، کاملاً از هم پاشیدم، چون تنها چیزی را پیشنهاد می‌کرد که هرگز به خودم اجازه نداده بودم امیدش را داشته باشم: امکان بخشش."),
            StoryParagraph("I hung up the phone, and I walked along the shore of the lake, and I watched the kites rise over the Golden Gate Park, kites of every color, rising and dipping and dancing in the wind, and I thought of Hassan, and I thought of the alley, and I thought of what I had done and what I had failed to do, and I wept, alone, in a park in California, for a boy I had betrayed thirty years ago in Afghanistan.", "گوشی را گذاشتم و در کنار ساحل دریاچه قدم زدم و تماشا کردم بادبادک‌ها بر فراز پارک گلدن گیت بالا می‌روند، بادبادک‌هایی به هر رنگ، بالا می‌رفتند و پایین می‌آمدند و در باد می‌رقصیدند و به حسن فکر کردم و به کوچه فکر کردم و به آنچه کرده بودم و آنچه نکرده بودم فکر کردم و گریستم، تنها، در پارکی در کالیفرنیا، برای پسری که سی سال پیش در افغانستان به او خیانت کرده بودم."),
            StoryParagraph("The past is never past, I realized, not for those of us who carry guilt, not for those of us who have failed to act when action was most needed, not for those of us who have watched suffering and done nothing to stop it, and I understood, in that moment, that the only way to be free of my past was to return to it, to face it, to atone for it.", "دریافتم گذشته هرگز گذشته نیست، نه برای کسانی از ما که گناه حمل می‌کنیم، نه برای کسانی از ما که وقتی عمل به‌شدت لازم بود، از عمل کردن ناتوان ماندیم، نه برای کسانی از ما که رنج را تماشا کرده‌ایم و برای متوقف کردنش هیچ نکرده‌ایم و در آن لحظه فهمیدم تنها راه آزادی از گذشته‌ام بازگشت به آن است، رویارویی با آن، کفاره‌اش."),
            StoryParagraph("I was born in Kabul, in 1963, in the same house where my father, Baba, had been born, and where his father before him had been born, into a family that had been prominent and respected for generations, into a world of privilege and comfort that I did not understand, at the time, was built on foundations that were already beginning to crack.", "من در کابل زاده شدم، در ۱۹۶۳، در همان خانه‌ای که پدرم بابا در آن زاده شده بود و پدر خودش پیش از او در آن زاده شده بود، در خانواده‌ای که نسل‌ها برجسته و محترم بود، در جهانی از امتیاز و راحتی که آن موقع نمی‌فهمیدم روی پایه‌هایی بنا شده که از قبل شروع به ترک خوردن کرده بودند."),
            StoryParagraph("My father was a man of great power and greater pride, a man whose word was law in our household, a man whose reputation extended far beyond the walls of our home, a man who had wrestled a bear once, or so the story went, and who had built, with his own hands, the most beautiful house in the Wazir Akbar Khan district.", "پدرم مردی با قدرت فراوان و غرور بیشتر بود، مردی که کلامش قانون خانه‌مان بود، مردی که آوازه‌اش بسیار فراتر از دیوارهای خانه‌مان می‌رفت، مردی که یک بار با خرسی کشتی گرفته بود، یا این‌گونه می‌گفتند، و با دستان خودش زیباترین خانه در منطقه وزیر اکبرخان را ساخته بود."),
            StoryParagraph("He had built the most beautiful house in the Wazir Akbar Khan district, a house of marble and gold, a house that was the envy of all who saw it, a house that was, in some ways, a monument to his own greatness, a house that I would one day have to leave, and that I would never, in my heart, truly leave.", "او زیباترین خانه در منطقه وزیر اکبرخان ساخته بود، خانه‌ای از مرمر و طلا، خانه‌ای که حسادت هر کس که می‌دیدش را برمی‌انگیخت، خانه‌ای که از بعضی جهات، بنای عظمت خودش بود، خانه‌ای که روزی مجبور می‌شدم ترکش کنم و در قلبم، هرگز واقعاً ترکش نمی‌کردم."),
            StoryParagraph("My mother had died giving birth to me, and Baba had raised me alone, or as alone as a man of his position could be, with the help of Ali and Hassan, our servants, who lived in a small mud hut at the end of the garden, and who were, though I did not know it at the time, the closest thing to family I would ever have.", "مادرم هنگام زایمان من مرده بود و بابا مرا تنها بزرگ کرده بود، یا تا آنجا که مردی با موقعیت او می‌توانست تنها باشد، با کمک علی و حسن، خدمتکارانمان که در کلبه‌ای گلی کوچک در انتهای باغ زندگی می‌کردند و هرچند آن موقع نمی‌دانستم، نزدیک‌ترین چیز به خانواده‌ای بودند که هرگز داشتم."),
            StoryParagraph("Ali was a Hazara, a member of the ethnic minority that had been despised and oppressed in Afghanistan for centuries, and Hassan was his son, a boy of my own age, my playmate, my friend, and — though I did not know it then — my brother, the half-brother that my father had never acknowledged, the secret that Baba had carried to his grave.", "علی هزاره بود، عضوی از اقلیت قومی که قرن‌ها در افغانستان خوار و مظلوم شده بود و حسن پسرش بود، پسری هم‌سن من، هم‌بازی‌ام، دوستم و — هرچند آن موقع نمی‌دانستم — برادرم، برادر ناتنی‌ای که پدرم هرگز به آن اعتراف نکرده بود، رازی که بابا تا گور با خود برده بود."),
            StoryParagraph("Ali's face was paralyzed on one side, the result of a childhood illness, and his smile, when it came, was crooked and strange, and the other children made fun of him, and Baba, who was not always a kind man, told me once that Ali was a good man, a loyal man, and that his face was the face of a man who had suffered.", "صورت علی از یک طرف فلج بود، نتیجه بیماری‌ای در کودکی و لبخندش، وقتی می‌آمد، کج و عجیب بود و بچه‌های دیگر مسخره‌اش می‌کردند و بابا، که همیشه مرد مهربانی نبود، یک بار به من گفت علی مرد خوبی است، مردی وفادار و صورتش صورت مردی است که رنج کشیده."),
            StoryParagraph("Hassan had a cleft lip, a harelip, that had been surgically repaired, and it left a small scar above his mouth, and Baba paid for the surgery, and I did not know, at the time, why Baba would pay so much money for the son of a servant, why he seemed to care for Hassan with a tenderness that he never showed to me.", "حسن لب‌شکری داشت، لبی شکافته که با جراحی درست شده بود و جای زخم کوچکی بالای دهانش گذاشته بود و بابا هزینه جراحی را پرداخت و آن موقع نمی‌دانستم چرا بابا اینقدر پول برای پسر یک خدمتکار می‌دهد، چرا به نظر می‌رسید با لطافتی که هرگز به من نشان نمی‌داد از حسن مراقبت می‌کند."),
            StoryParagraph("Hassan and I grew up together, nursed by the same woman, played in the same alleys, and though he was a Hazara and I was a Pashtun, though he was a servant and I was a master, we were inseparable, and I loved him, and I believed that he loved me, and for those early years, that was enough.", "حسن و من با هم بزرگ شدیم، توسط همان زن شیر خوردیم، در همان کوچه‌ها بازی کردیم و هرچند او هزاره بود و من پشتون، هرچند او خدمتکار بود و من ارباب، از هم جدا نمی‌شدیم و او را دوست داشتم و باور داشتم او هم دوستم دارد و برای آن سال‌های نخست، همین کافی بود."),
            StoryParagraph("But I know now that there was always something I did not acknowledge, some shadow that hovered at the edges of our friendship, some knowledge that I kept hidden even from myself, some distance that I created, even if I did not admit that I was creating it, some seed of betrayal that was planted, from the very beginning, in the soil of our love.", "اما حالا می‌دانم همیشه چیزی بود که به آن اعتراف نمی‌کردم، سایه‌ای که در لبه‌های دوستی‌مان پرسه می‌زد، دانشی که حتی از خودم پنهانش می‌کردم، فاصله‌ای که می‌ساختم، حتی اگر اعتراف نمی‌کردم که می‌سازمش، بذری از خیانت که از همان آغاز، در خاک عشقمان کاشته شده بود."),
            StoryParagraph("I was a Pashtun, and Hassan was a Hazara, and in Afghanistan, that difference meant everything; it meant that I could go to school and he could not; it meant that I would grow up to be a man of status and he would grow up to be a servant; it meant that our lives, however joined in childhood, would one day be separated by a gulf that no friendship could bridge.", "من پشتون بودم و حسن هزاره و در افغانستان، این تفاوت یعنی همه چیز؛ یعنی من می‌توانستم به مدرسه بروم و او نمی‌توانست؛ یعنی من بزرگ می‌شدم و مردی با منزلت می‌شدم و او بزرگ می‌شد و خدمتکاری؛ یعنی زندگی‌هایمان، هر چقدر هم که در کودکی به هم پیوسته باشند، روزی توسط شکافی از هم جدا می‌شدند که هیچ دوستی نمی‌توانست پلش کند."),
            StoryParagraph("And yet, in those early years, none of that mattered; in those early years, we were simply two boys, playing in the streets of Kabul, flying kites, telling stories, and dreaming of a future in which nothing would ever change, in which the summers would always be warm and the winters would always bring snow and the kites would always rise against a pale grey sky.", "و با این حال، در آن سال‌های نخست، هیچ‌کدام از این‌ها مهم نبود؛ در آن سال‌های نخست، ما فقط دو پسر بودیم، در خیابان‌های کابل بازی می‌کردیم، بادبادک می‌پراندیم، داستان می‌گفتیم و در خواب آینده‌ای می‌دیدیم که در آن هیچ چیز هرگز تغییر نمی‌کرد، آینده‌ای که در آن تابستان‌ها همیشه گرم می‌بود و زمستان‌ها همیشه برف می‌آورد و بادبادک‌ها همیشه در آسمان خاکستری روشن بالا می‌رفتند."),
            StoryParagraph("I remember the winters most of all, the winters of Kabul, when the snow fell thick and soft and the whole city seemed to be wrapped in silence, when Hassan and I would spend our days reading, or telling stories, or watching the kites rise against a pale grey sky.", "بیش از همه زمستان‌ها را به یاد می‌آورم، زمستان‌های کابل، وقتی برف غلیظ و نرم می‌بارید و تمام شهر به نظر در سکوت پیچیده می‌شد، وقتی حسن و من روزهایمان را با خواندن یا داستان گفتن یا تماشای بالا رفتن بادبادک‌ها در آسمان خاکستری روشن می‌گذراندیم."),
            StoryParagraph("Hassan loved stories; he loved them more than anything, and he would sit beside me for hours, listening as I read from the books Baba gave me, or as I made up tales of my own, tales of heroes and villains and magical lands, and he would listen with his whole body, with his whole being, as if each word were a treasure that he was being given.", "حسن داستان‌ها را دوست می‌داشت؛ بیشتر از هر چیزی دوستشان می‌داشت و ساعت‌ها کنارم می‌نشست، گوش می‌داد همان‌طور که از کتاب‌هایی که بابا به من می‌داد می‌خواندم یا همان‌طور که داستان‌های خودم را می‌ساختم، داستان‌هایی از قهرمانان و اشرار و سرزمین‌های جادویی و با تمام بدنش گوش می‌داد، با تمام وجودش، گویی هر کلمه گنجی بود که به او داده می‌شد."),
            StoryParagraph("'Amir agha,' he would say, and his voice was full of wonder, 'will you read to me again tomorrow?' And I would say yes, and I would read to him, and I would feel, in those moments, a sense of power and importance that I did not feel anywhere else, and I would realize, even then, that this power was not innocent, that it was built on his ignorance and my privilege, that it was, in some ways, a small act of cruelty.", "می‌گفت: «امیر آقا،» و صدایش پر از شگفتی بود، «فردا دوباره برایم می‌خوانی؟» و من بله می‌گفتم و برایش می‌خواندم و در آن لحظه‌ها، حسی از قدرت و اهمیت داشتم که هیچ جای دیگری نداشتم و حتی آن موقع هم دریافتم که این قدرت بی‌گناه نبود، روی جهل او و امتیاز من بنا شده بود، از بعضی جهات، عمل کوچکی از بی‌رحمی بود."),
            StoryParagraph("But I was not a good boy, not really; I was a boy who was often cruel, often jealous, often too cowardly to stand up for what was right, and Hassan, who loved me, who trusted me, who would have done anything for me, was the one who suffered most from my failings, the one who absorbed my cruelty without complaint, the one who forgave me, again and again, without being asked.", "اما پسر خوبی نبودم، نه واقعاً؛ پسری بودم که اغلب بی‌رحم بود، اغلب حسود، اغلب بیش از حد بزدل که برای آنچه درست است بایستد و حسن، که دوستم داشت، که به من اعتماد داشت، که هر کاری برایم می‌کرد، کسی بود که بیشتر از همه از کاستی‌های من رنج می‌کشید، کسی که بی‌رحمی‌ام را بدون شکایت جذب می‌کرد، کسی که بی‌آنکه خواسته شود، بارها و بارها می‌بخشید."),
            StoryParagraph("I laughed, sometimes, when the other boys teased him; I pretended, sometimes, that I did not hear; I turned away, sometimes, when I should have turned toward him, and each time I did this, I felt a small pain in my chest, a pain that I told myself was nothing, a pain that I learned, over the years, to ignore, to bury, to forget.", "گاهی می‌خندیدم، وقتی پسرهای دیگر مسخره‌اش می‌کردند؛ گاهی تظاهر می‌کردم نمی‌شنوم؛ گاهی رو می‌گرداندم، وقتی باید به سمتش می‌چرخیدم و هر بار که این کار را می‌کردم، درد کوچکی در سینه‌ام حس می‌کردم، دردی که به خودم می‌گفتم هیچ است، دردی که در طول سال‌ها یاد گرفتم نادیده بگیرم، دفن کنم، فراموش کنم."),
            StoryParagraph("And each time I did this, I felt a small pain in my chest, a pain that I told myself was nothing, a pain that I learned, over the years, to ignore, to bury, to forget — until, many years later, in a hospital room in Islamabad, the pain returned, and I could no longer ignore it, and I knew that I would have to face it.", "و هر بار که این کار را می‌کردم، درد کوچکی در سینه‌ام حس می‌کردم، دردی که به خودم می‌گفتم هیچ است، دردی که در طول سال‌ها یاد گرفتم نادیده بگیرم، دفن کنم، فراموش کنم — تا اینکه سال‌ها بعد، در اتاق بیمارستانی در اسلام‌آباد، درد بازگشت و دیگر نتوانستم نادیده‌اش بگیرم و دانستم که باید با آن روبرو شوم."),
            StoryParagraph("For this is the story of my life: the story of a boy who failed, and who spent his life trying to make up for that failure; the story of a friendship that was betrayed, and of a betrayal that could never be undone; the story of a sin that could not be forgiven, and of a forgiveness that came, in the end, not from others but from within.", "زیرا این داستان زندگی من است: داستان پسری که شکست خورد و عمرش را صرف تلاش برای جبران آن شکست کرد؛ داستان دوستی‌ای که خیانت شد و خیانتی که هرگز نمی‌شد جبرانش کرد؛ داستان گناهی که نمی‌شد بخشید و بخششی که در پایان، نه از دیگران بلکه از درون آمد."),
            StoryParagraph("And it is the story of Afghanistan, my homeland, a land that has been torn apart by war and invasion and hatred, a land that has suffered more than any land should have to suffer, a land that I love, and that I betrayed, and that I tried, in the end, to save.", "و داستان افغانستان است، سرزمین مادری‌ام، سرزمینی که توسط جنگ و اشغال و نفرت تکه‌تکه شده، سرزمینی که بیش از آنچه هر سرزمینی باید تحمل کند رنج کشیده، سرزمینی که دوستش دارم و به آن خیانت کردم و در پایان تلاش کردم نجاتش دهم."),
            StoryParagraph("I was born in Kabul, and I returned to Kabul, and between those two events, a lifetime passed, a lifetime of guilt and redemption and the long, painful process of learning to be good again.", "من در کابل زاده شدم و به کابل بازگشتم و میان آن دو واقعه، عمری گذشت، عمری از گناه و رستگاری و فرایند طولانی و دردناک یادگیری دوباره خوب بودن."),
            StoryParagraph("But the story does not begin in Kabul, and it does not end there either; it begins in the heart of a boy who did not know how to be brave, and it ends, if it ends at all, in the heart of a man who has learned, at last, what it means to be good.", "اما داستان در کابل آغاز نمی‌شود و آنجا هم پایان نمی‌یابد؛ در قلب پسری آغاز می‌شود که نمی‌دانست چطور شجاع باشد و در قلب مردی پایان می‌یابد، اگر اصلاً پایان یابد، که سرانجام آموخته خوب بودن یعنی چه."),
            StoryParagraph("So let me begin where the story truly begins, in the winter of 1975, in the streets of Kabul, on the day I became what I am today, the day of the kite tournament, the day I watched my friend being hurt and did nothing, the day I lost, forever, the right to call myself his friend.", "پس بگذارید آنجا آغاز کنم که داستان واقعاً آغاز می‌شود، در زمستان ۱۹۷۵، در خیابان‌های کابل، در روزی که آنچه امروز هستم شدم، روز مسابقه بادبادک، روزی که تماشا کردم دوستم آسیب می‌بیند و هیچ نکردم، روزی که برای همیشه، حق اینکه خودم را دوستش بنامم از دست دادم."),
            StoryParagraph("For on that day, in that alley, I learned something that I have never been able to unlearn: that courage is not the absence of fear, but the willingness to act in spite of it, and that I, on that day, was not brave, that I have, in fact, never been brave, that I have spent my life pretending to be something I am not.", "زیرا در آن روز، در آن کوچه، چیزی آموختم که هرگز نتوانسته‌ام از یاد ببرم: که شجاعت نبود ترس نیست، بلکه آمادگی عمل کردن به رغم آن است و من، در آن روز، شجاع نبودم، که در واقع، هرگز شجاع نبوده‌ام، که عمرم را صرف تظاهر به چیزی کرده‌ام که نیستم."),
            StoryParagraph("And I have spent my life, since then, trying to become the man I should have been on that day, in that alley, when Hassan needed me, when Hassan called out for me, when Hassan trusted me to save him, and I did not.", "و از آن زمان، عمرم را صرف تلاش کرده‌ام تا مردی شوم که باید در آن روز می‌بودم، در آن کوچه، وقتی حسن نیازم داشت، وقتی حسن صدایم زد، وقتی حسن به من اعتماد کرد تا نجاتش دهم و من ندادم."),
            StoryParagraph("That is my story, and that is what I must tell you, from beginning to end, in all its shame and all its sorrow and all its strange, unexpected hope.", "این داستان من است و این همان چیزی است که باید برایتان بگویم، از آغاز تا پایان، با تمام شرمش و تمام اندوهش و تمام امید عجیب و غیرمنتظره‌اش."),
            StoryParagraph("For in telling it, I may, at last, find the way to be good again.", "زیرا در تعریفش، شاید، سرانجام راه دوباره خوب بودن را بیابم."),
            StoryParagraph("And that, in the end, is all I want — to be good again, to be the person Hassan believed I could be, to be worthy of the love he gave me so freely, so unconditionally, so completely.", "و این، در پایان، تمام چیزی است که می‌خواهم — دوباره خوب بودن، شخصی بودن که حسن باور داشت می‌توانم باشم، سزاوار عشقی بودن که او اینقدر آزادانه به من داد، اینقدر بی‌قید و شرط، اینقدر کامل."),
            StoryParagraph("For Hassan, who could not read, who did not have an education, who had nothing in this world, gave me the one thing that no one else ever has: the gift of being loved, truly loved, without condition, without judgment, without reservation.", "زیرا حسن، که نمی‌توانست بخواند، که تحصیل نداشت، که در این دنیا هیچ نداشت، تنها چیزی را به من داد که هیچ‌کس دیگری هرگز نداده بود: هدیه دوست داشته شدن، به‌راستی دوست داشته شدن، بی‌قید و شرط، بدون قضاوت، بدون تردید."),
            StoryParagraph("And I, who could read, who had an education, who had everything in this world, repaid that love with betrayal, and I have carried that betrayal with me every day since, like a stone in my chest, like a wound that will not heal, like a name I can no longer say without shame.", "و من، که می‌توانستم بخوانم، که تحصیل داشتم، که در این دنیا همه چیز داشتم، آن عشق را با خیانت جبران کردم و از آن زمان هر روز آن خیانت را با خود حمل کرده‌ام، همچون سنگی در سینه‌ام، همچون زخمی که التیام نمی‌یابد، همچون نامی که دیگر نمی‌توانم بدون شرم بگویمش."),
            StoryParagraph("But perhaps, if I tell the story, if I speak the truth, if I finally say his name aloud, without shame, without fear, without pretense, then the wound may begin to heal, and I may begin to become the man he believed I could be.", "اما شاید، اگر داستان را بگویم، اگر حقیقت را بگویم، اگر سرانجام نامش را بلند بگویم، بدون شرم، بدون ترس، بدون تظاهر، آنگاه زخم شروع به التیام کند و من شروع کنم به شدن مردی که او باور داشت می‌توانم باشم."),
            StoryParagraph("So this is my story, the story of a kite runner and the boy who betrayed him, the story of a friendship and a betrayal and a long, painful journey toward redemption, the story of Afghanistan and of America and of all the places in between.", "پس این داستان من است، داستان بادبادک‌بازی و پسری که به او خیانت کرد، داستان دوستی و خیانت و سفری طولانی و دردناک به سوی رستگاری، داستان افغانستان و آمریکا و همه جاهای میانشان."),
            StoryParagraph("For I have learned, at last, that there is a way to be good again, that redemption is possible, that the past, though it cannot be changed, can be confronted, and that the one who confronts it, however late, however imperfectly, is already on the path toward becoming whole.", "زیرا سرانجام آموخته‌ام راهی برای دوباره خوب بودن هست، که رستگاری ممکن است، که گذشته، هرچند نمی‌توان تغییرش داد، می‌توان با آن روبرو شد و کسی که با آن روبرو شود، هر چقدر هم دیر، هر چقدر هم ناقص، از قبل در راه شدن به تمامیت است."),
            StoryParagraph("And so my story begins, in Kabul, in 1975, on the day of the kite tournament, on the day I became what I am today.", "و اینگونه داستانم آغاز می‌شود، در کابل، در ۱۹۷۵، در روز مسابقه بادبادک، در روزی که آنچه امروز هستم شدم.")
        )
    )

    // ─────────── فصل ۲: بادبادک‌ها ───────────
    private fun chapter2() = StoryChapter(
        number = 2, title = "Kites", titlePersian = "بادبادک‌ها",
        paragraphs = listOf(
            StoryParagraph("Winter was the season of kites in Kabul, and the kite-fighting tournament was the most important event of the year, an event that every boy in the city looked forward to with a passion that adults reserved for things like weddings and births and the return of loved ones from long journeys.", "زمستان فصل بادبادک در کابل بود و مسابقه بادبادک‌بازی مهم‌ترین رویداد سال بود، رویدادی که هر پسری در شهر با شوری انتظارش را می‌کشید که بزرگسالان برای چیزهایی چون عروسی و تولد و بازگشت عزیزان از سفرهای طولانی نگه می‌داشتند."),
            StoryParagraph("The rules were simple: you flew your kite, you maneuvered it against the kites of others, and you tried to cut their strings with your own, using a string coated in ground glass, and the last kite still flying was the winner, the champion, the boy who would be celebrated for a year.", "قوانین ساده بودند: بادبادکت را می‌پراندی، آن را در برابر بادبادک‌های دیگران مانور می‌دادی و تلاش می‌کردی رشته‌شان را با رشته خودت ببری، با استفاده از رشته‌ای پوشیده در شیشه کوبیده و آخرین بادبادکی که هنوز پرواز می‌کرد برنده بود، قهرمان، پسری که یک سال جشن گرفته می‌شد."),
            StoryParagraph("But kite-fighting was not just about cutting strings; it was about chasing down the fallen kites, about running through the streets of Kabul with the other boys, about claiming the defeated kites as your prize, about proving, once again, that you were a champion, that you were the best, that you were worthy of respect.", "اما بادبادک‌بازی تنها درباره بریدن رشته‌ها نبود؛ درباره تعقیب بادبادک‌های افتاده بود، درباره دویدن در خیابان‌های کابل با پسرهای دیگر، درباره به چنگ آوردن بادبادک‌های شکست‌خورده همچون جایزه و درباره اثبات، یک بار دیگر، که قهرمان بودی، که بهترین بودی، که سزاوار احترام بودی."),
            StoryParagraph("Hassan was the best kite runner in Kabul; no one could chase down a fallen kite as quickly or as surely as he could, no one knew the streets and alleys of the city as intimately as he did, no one could predict, with such uncanny accuracy, where a kite would land before it had even begun to fall.", "حسن بهترین بادبادک‌باز کابل بود؛ هیچ‌کس نمی‌توانست به سرعت یا به‌قدر مطمئن او بادبادکی افتاده را تعقیب کند، هیچ‌کس کوچه و خیابان‌های شهر را به اندازه او از نزدیک نمی‌شناخت، هیچ‌کس نمی‌توانست با چنین دقت مرموزی پیش‌بینی کند بادبادکی پیش از آنکه حتی شروع به افتادن کرده باشد کجا فرود می‌آید."),
            StoryParagraph("And I was the best kite flyer, or at least I believed I was, or at least I wanted to believe I was, and together, Hassan and I made a team that no one could beat, a team that was celebrated throughout the neighborhood, a team that was, in the small world of Kabul's children, legendary.", "و من بهترین بادبادک‌پران بودم، یا حداقل باور داشتم بودم، یا حداقل می‌خواستم باور کنم بودم و با هم، حسن و من تیمی می‌ساختیم که هیچ‌کس نمی‌توانست ببردش، تیمی که در تمام محله جشن گرفته می‌شد، تیمی که در جهان کوچک بچه‌های کابل، افسانه‌ای بود."),
            StoryParagraph("We had a pact, Hassan and I, a pact that we had made when we were very young, a pact that we never broke, or that I never broke, because Hassan, I knew, would never break it, whatever the cost, however great the sacrifice, whatever the pain that loyalty might require of him.", "حسن و من پیمانی داشتیم، پیمانی که وقتی خیلی کوچک بودیم بسته بودیم، پیمانی که هرگز نشکستیم، یا من هرگز نشکستم، چون حسن، می‌دانستم، هرگز نمی‌شکستش، هر هزینه‌ای هم داشت، هر فداکاری‌ای هم که بزرگ بود، هر دردی هم که وفاداری از او می‌خواست."),
            StoryParagraph("'Whatever happens,' I had said to him, one day, when we were playing in the garden, 'I will never hurt you. I will always protect you.' And Hassan, who had believed me, who had trusted me with all his heart, had answered, 'I know, Amir agha. I know you will always protect me.'", "یک روز که در باغ بازی می‌کردیم به او گفته بودم: «هر چه پیش بیاید، هرگز آزارت نمی‌دهم. همیشه محافظتت می‌کنم.» و حسن، که باور کرده بود، که با تمام قلبش اعتماد کرده بود پاسخ داده بود: «می‌دانم، امیر آقا. می‌دانم همیشه محافظتم می‌کنی.»"),
            StoryParagraph("But I did not protect him; when the time came to protect him, I did nothing; I stood at the mouth of an alley and watched, and I did not move, and I did not speak, and I let him be hurt, and then I pretended, for years, that I had not been there, that I had not seen, that I was not, in fact, a witness to his suffering.", "اما محافظتش نکردم؛ وقتی وقتش رسید که محافظتش کنم، هیچ نکردم؛ در دهانه کوچه ایستادم و تماشا کردم و تکان نخوردم و چیزی نگفتم و گذاشتم آسیب ببیند و بعد سال‌ها تظاهر کردم آنجا نبودم، ندیدم، که در واقع، شاهد رنجش نبودم."),
            StoryParagraph("The kite tournament of 1975 was the greatest tournament of my childhood, and I knew, from the moment the first kites rose into the sky, from the moment I felt the string tighten in my hand, from the moment I heard the wind whistle through the paper, that this was my day, that this was the day I would prove myself, at last, to Baba.", "مسابقه بادبادک ۱۹۷۵ بزرگ‌ترین مسابقه کودکی‌ام بود و از لحظه‌ای که اولین بادبادک‌ها به آسمان بلند شدند، از لحظه‌ای که رشته را در دستم سخت حس کردم، از لحظه‌ای که شنیدم باد از میان کاغذ سوت می‌زند، می‌دانستم این روز من است، این روزی است که بالاخره خودم را به بابا ثابت می‌کنم."),
            StoryParagraph("Baba did not love me, or did not love me as I needed to be loved, and I knew this, and it hurt, and I tried, with all my might, to earn his affection, to be the son he wanted, to be strong and brave and confident, to be everything I was not.", "بابا دوستم نداشت، یا آن‌طور که نیاز داشتم دوستم نداشت و این را می‌دانستم و درد داشت و با تمام نیرو تلاش می‌کردم محبتش را به دست آورم، پسری باشم که می‌خواست، قوی و شجاع و با اعتماد به نفس باشم، هر چیزی که نبودم باشم."),
            StoryParagraph("But the more I tried, the more I failed, for I was not my father; I was a boy who cried when he was hurt, who read poetry when he should have been playing sports, who preferred stories to guns, who could not, no matter how hard he tried, be the man Baba wanted him to be.", "اما هر چه بیشتر تلاش می‌کردم بیشتر شکست می‌خواستم، چون من پدرم نبودم؛ پسری بودم که وقتی آسیب می‌دید گریه می‌کرد، که وقتی باید ورزش می‌کرد شعر می‌خواند، که داستان را به تفنگ ترجیح می‌داد، که نمی‌توانست، هر چقدر هم تلاش می‌کرد، مردی باشد که بابا می‌خواست."),
            StoryParagraph("And so I threw myself into the kite tournament, and I flew my kite against the kites of the city, and one by one, they fell, and one by one, Hassan ran to retrieve them, and the crowd of boys in the streets grew, and the cheers grew louder, and for a moment, I felt as if I might actually win, as if I might, at last, be worthy of my father's love.", "و اینگونه خودم را در مسابقه بادبادک انداختم و بادبادکم را در برابر بادبادک‌های شهر پراندم و یکی‌یکی افتادند و یکی‌یکی حسن دوید تا برشان دارد و جمعیت پسرها در خیابان‌ها بیشتر شد و هوراها بلندتر و برای لحظه‌ای، حس کردم ممکن است واقعاً برنده شوم، ممکن است سرانجام سزاوار عشق پدرم باشم."),
            StoryParagraph("And then, at last, there were only two kites left in the sky, mine and the kite of the boy with the blue kite, and I knew that if I could cut the blue kite, if I could bring it down, I would be the champion, and Baba would be proud of me, and everything would be different.", "و سپس، سرانجام، تنها دو بادبادک در آسمان ماند، مال من و بادبادک پسر با بادبادک آبی و می‌دانستم اگر بتوانم بادبادک آبی را ببرم، اگر بتوانم پایینش بیاورم، قهرمان می‌شوم و بابا به من افتخار می‌کند و همه چیز متفاوت می‌شود."),
            StoryParagraph("The blue kite was a beautiful kite, a kite that had been made with care and skill, a kite that was the pride of its owner, a boy named Assef, a boy who was known throughout the neighborhood for his cruelty and his violence and his hatred of the Hazara, a boy who would, in the years to come, become something far worse than a bully.", "بادبادک آبی بادبادکی زیبا بود، بادبادکی که با دقت و مهارت ساخته شده بود، بادبادکی که افتخار صاحبش بود، پسری به نام آصف، پسری که در تمام محله به‌خاطر بی‌رحمی و خشونت و نفرتش از هزاره شناخته می‌شد، پسری که در سال‌های بعد، به چیزی بسیار بدتر از یک قلدر تبدیل می‌شد."),
            StoryParagraph("I had seen Assef hurt other boys, hurt them badly, and I had seen Hassan in the crowd at the tournament, cheering me on, and I had seen Assef look at Hassan, and I had seen the hatred in his eyes, and I had felt, somewhere deep inside me, a warning that I did not want to hear.", "دیده بودم آصف پسرهای دیگر را آسیب می‌زند، بدجور آسیب می‌زند و دیده بودم حسن در جمعیت مسابقه ایستاده، تشویقم می‌کند و دیده بودم آصف به حسن نگاه می‌کند و نفرت در چشمانش دیده بودم و جایی در عمق وجودم، هشداری حس کرده بودم که نمی‌خواستم بشنوم."),
            StoryParagraph("But I did not think of these things as I flew my kite; I thought only of winning, only of Baba, only of the moment when I would bring the blue kite down and prove, at last, that I was worthy of my father's love, that I was not the disappointment he had always believed me to be.", "اما همانطور که بادبادکم را می‌پراند به این چیزها فکر نکردم؛ تنها به بردن فکر کردم، تنها به بابا، تنها به لحظه‌ای که بادبادک آبی را پایین می‌آوردم و سرانجام ثابت می‌کردم که سزاوار عشق پدرم هستم، که ناامیدی‌ای که او همیشه باور داشت هستم، نیستم."),
            StoryParagraph("And then the moment came: my kite dipped, then rose, then swung in a wide arc, and the string of my kite crossed the string of the blue kite, and I pulled, hard, and the string of the blue kite snapped, and the blue kite fell, and I had won.", "و بعد لحظه آمد: بادبادکم افتاد، بعد برخاست، بعد در قوسی عریض چرخید و رشته بادبادکم از رشته بادبادک آبی گذشت و محکم کشیدم و رشته بادبادک آبی پاره شد و بادبادک آبی افتاد و برده بودم."),
            StoryParagraph("The crowd of boys cheered, and I felt a joy that I had never felt before, a joy that was pure and bright and almost painful in its intensity, and I knew that this was the moment I had been waiting for, the moment of my triumph, the moment that would define me, for better or worse, for the rest of my life.", "جمعیت پسرها هورا کشیدند و شادی‌ای حس کردم که هرگز قبلاً حس نکرده بودم، شادی‌ای خالص و روشن و تقریباً در شدتش دردناک و می‌دانستم این لحظه‌ای بود که منتظرش بودم، لحظه پیروزی‌ام، لحظه‌ای که برای بهتر یا بدتر، برای باقی عمرم تعریفم می‌کرد."),
            StoryParagraph("'Hassan,' I shouted, 'the blue kite! Go get it!'", "فریاد زدم: «حسن، بادبادک آبی! برو بیاورش!»"),
            StoryParagraph("And Hassan, my friend, my kite runner, my brother, turned and ran, ran through the streets of Kabul, ran with the wind in his hair and the joy of the chase in his heart, ran to retrieve the blue kite that would prove, forever, that I was a champion.", "و حسن، دوستم، بادبادک‌بازم، برادرم، چرخید و دوید، در خیابان‌های کابل دوید، با باد در موهایش و شوق تعقیب در قلبش دوید تا بادبادک آبی را بیاورد، بادبادکی که برای همیشه ثابت می‌کرد قهرمانم."),
            StoryParagraph("And I followed him, slowly at first, then faster, because I wanted to be there when he found the kite, because I wanted to hold it in my hands, because I wanted to feel, just once, what it was like to be the winner.", "و دنبالش دویدم، اول آهسته، بعد تندتر، چون می‌خواستم وقتی بادبادک را پیدا می‌کند آنجا باشم، چون می‌خواستم آن را در دستانم بگیرم، چون می‌خواستم یک بار هم که شده حس کنم برنده بودن چه شکلی است."),
            StoryParagraph("But when I found him, when I turned the corner into that alley, what I saw would change me forever, would haunt me for the rest of my life, would become the wound that never healed, the memory that never faded, the guilt that never went away.", "اما وقتی پیدایش کردم، وقتی از آن پیچ به آن کوچه وارد شدم، آنچه دیدم برای همیشه تغییرم می‌داد، باقی عمرم تسخیرم می‌کرد، زخمی می‌شد که هرگز التیام نمی‌یافت، خاطره‌ای که هرگز محو نمی‌شد، گناهی که هرگز از بین نمی‌رفت."),
            StoryParagraph("I saw Hassan, standing in the alley, the blue kite in his hands, and I saw three other boys, older boys, boys with cruelty in their eyes, and one of them was Assef, and they were surrounding Hassan, and Hassan was afraid.", "حسن را دیدم، در کوچه ایستاده، بادبادک آبی در دستانش و سه پسر دیگر دیدم، پسرهای بزرگ‌تر، پسرهایی با بی‌رحمی در چشمانشان و یکی‌شان آصف بود و احاطه‌اش کرده بودند و حسن ترسیده بود."),
            StoryParagraph("And I stood at the mouth of the alley, and I watched, and I did not move, and I did not speak, and I let them do what they did, and then I let them walk away, and then I let Hassan walk away, and then I followed him, and I did not say a word, and I have not, in all the years since, been able to forgive myself for that silence.", "و در دهانه کوچه ایستادم و تماشا کردم و تکان نخوردم و چیزی نگفتم و گذاشتم هر کاری که کردند بکنند و بعد گذاشتم بروند و بعد گذاشتم حسن برود و بعد دنبالش رفتم و یک کلمه هم نگفتم و در تمام سال‌های بعد، نتوانسته‌ام خودم را برای آن سکوت ببخشم."),
            StoryParagraph("I do not want to describe what they did to him; I have described it once before, and it was almost more than I could bear; I will simply say that it was the worst thing that I have ever seen, and that I stood there and did nothing, and that this is the thing that I have been trying, for the rest of my life, to atone for.", "نمی‌خواهم توصیف کنم چه کردند؛ یک بار قبلاً توصیفش کردم و تقریباً بیش از آن بود که تحمل کنم؛ فقط می‌گویم بدترین چیزی بود که تا حالا دیده‌ام و آنجا ایستادم و هیچ نکردم و این همان چیزی است که باقی عمرم تلاش کرده‌ام برایش کفاره بدهم."),
            StoryParagraph("And so ended the winter of 1975, the winter of the kite tournament, the winter I became what I am today, the winter that I have never been able to leave behind.", "و اینگونه زمستان ۱۹۷۵ پایان یافت، زمستان مسابقه بادبادک، زمستانی که آنچه امروز هستم شدم، زمستانی که هرگز نتوانسته‌ام پشت سر بگذارم."),
            StoryParagraph("For even now, decades later, on the other side of the world, in a country that is not my own, I still see that alley when I close my eyes, and I still hear Hassan's silence, and I still feel the weight of my own cowardice.", "زیرا حتی حالا، دهه‌ها بعد، در آن سوی دنیا، در سرزمینی که مال من نیست، وقتی چشمانم را می‌بندم هنوز آن کوچه را می‌بینم و هنوز سکوت حسن را می‌شنوم و هنوز وزن بزدلی خودم را حس می‌کنم."),
            StoryParagraph("And I know, at last, that the only way to be free of the past is to face it, to accept it, to atone for it — and that this is what Rahim Khan was telling me, on the phone, from the other side of the world.", "و سرانجام می‌دانم که تنها راه آزادی از گذشته رویارویی با آن است، پذیرشش، کفاره‌اش — و این همان چیزی است که رحیم‌خان، روی تلفن، از آن سوی دنیا به من می‌گفت."),
            StoryParagraph("There is a way to be good again.", "راهی برای دوباره خوب بودن هست."),
            StoryParagraph("And I knew, when I heard those words, that I would have to go back to Afghanistan.", "و وقتی آن کلمات را شنیدم، می‌دانستم که باید به افغانستان بازگردم."),
            StoryParagraph("Back to the place where I had been a coward.", "بازگشت به جایی که بزدل بوده بودم."),
            StoryParagraph("Back to the place where I had lost my brother.", "بازگشت به جایی که برادرم را از دست داده بودم."),
            StoryParagraph("Back to the place where I had to begin, at last, to become the man I should have been, all those years ago, in that alley.", "بازگشت به جایی که باید سرانجام شروع می‌کردم به شدن مردی که باید می‌بودم، تمام آن سال‌ها پیش، در آن کوچه."),
            StoryParagraph("And so the first part of my story ends, and the second part begins, the part about the journey, the part about the boy, the part about the redemption that I sought and that I was not sure I deserved.", "و اینگونه بخش نخست داستانم پایان می‌یابد و بخش دوم آغاز می‌شود، بخشی درباره سفر، بخشی درباره پسر، بخشی درباره رستگاری‌ای که در جستجویش بودم و مطمئن نبودم سزاوارش هستم."),
            StoryParagraph("And the second part begins with a journey, and with a boy, and with a promise that I made and that I would struggle, more than I had ever imagined, to keep.", "و بخش دوم با سفری آغاز می‌شود و با پسری و با قولی که دادم و برای نگه داشتنش بیشتر از آنچه تصور کرده بودم، تقلا می‌کردم."),
            StoryParagraph("For Hassan had a son, a boy named Sohrab, and I did not know, when I began my journey, that in saving him, I would also, at last, be saved.", "زیرا حسن پسری داشت، پسری به نام سهراب و وقتی سفرم را آغاز کردم، نمی‌دانستم با نجات دادن او، سرانجام، خودم هم نجات می‌یابم."),
            StoryParagraph("And that is the story I must now tell.", "و این همان داستانی است که باید اکنون بگویم.")
        )
    )
// ─────────── فصل ۳: فرار از کابل ───────────
private fun chapter3() = StoryChapter(
    number = 3, title = "Escape from Kabul", titlePersian = "فرار از کابل",
    paragraphs = listOf(
        StoryParagraph("The Soviet invasion came in 1979, when I was sixteen years old, and it changed everything, as invasions always do, sweeping away the world that had been and replacing it with one that no one could have predicted, a world in which the familiar became strange and the strange became normal and nothing, ever again, was as it had been before.", "اشغال شوروی در ۱۹۷۹ آمد، وقتی شانزده ساله بودم و همه چیز را تغییر داد، همانطور که اشغال‌ها همیشه می‌کنند، جهانی که بود را جارو کرد و جهانی جایش گذاشت که هیچ‌کس نمی‌توانست پیش‌بینی کند، جهانی که در آن آشنا غریب شد و غریب عادی و هیچ چیز، دیگر هرگز، همان‌طور که بوده نبود."),
        StoryParagraph("The streets of Kabul, once safe and familiar, became dangerous; the sound of gunfire became common; the faces of my childhood friends disappeared, one by one, as their families fled the country, and I watched this happen, and I did not know what to feel, because I was young, and because I had never known anything but Kabul, and because I could not imagine a world in which Kabul was not my home.", "خیابان‌های کابل، زمانی امن و آشنا، خطرناک شد؛ صدای شلیک رایج شد؛ چهره دوستان کودکی‌ام یکی‌یکی ناپدید شدند، همانطور که خانواده‌هایشان از کشور می‌گریختند و تماشا کردم این اتفاق می‌افتد و نمی‌دانستم چه حس کنم، چون جوان بودم و چون هرگز چیزی جز کابل نشناخته بودم و چون نمی‌توانستم جهانی را تصور کنم که در آن کابل خانه‌ام نباشد."),
        StoryParagraph("Baba, who had always been a man of principle, a man who spoke his mind, a man who did not bow to anyone, found himself in increasing danger, for the communists who had taken power did not tolerate men like him, men who had money and influence and the respect of the people, men who could, if they chose, become leaders of resistance.", "بابا، که همیشه مردی اصول‌گرا بود، مردی که حرف دلش را می‌زد، مردی که به هیچ‌کس خم نمی‌شد، خود را در خطر فزاینده یافت، چون کمونیست‌هایی که قدرت گرفته بودند مردانی مثل او را تحمل نمی‌کردند، مردانی که پول و نفوذ و احترام مردم را داشتند، مردانی که اگر می‌خواستند، می‌توانستند رهبران مقاومت شوند."),
        StoryParagraph("I remember the night we left Kabul as if it were yesterday; I remember the cold, the fear, the silence; I remember the way Baba held my hand and told me not to look back, even as I wanted to look back, even as I needed to look back, even as I knew that everything I loved was behind me and everything I did not know was ahead.", "شبی که کابل را ترک کردیم را مثل دیروز به یاد می‌آورم؛ سرما را به یاد می‌آورم، ترس را، سکوت را؛ شیوه‌ای که بابا دستم را گرفت و گفت برنگرد را به یاد می‌آورم، همانطور که می‌خواستم برگردم، همانطور که نیاز داشتم برگردم، همانطور که می‌دانستم هر چیزی که دوستش دارم پشت سرم است و هر چیزی که نمی‌شناسم پیش رویم."),
        StoryParagraph("But I did not look back, and I have never seen Kabul again, not the Kabul of my childhood, not the Kabul of my memory, not the Kabul that existed before the wars, and I have often wondered, in the years since, whether the city I remember ever truly existed, or whether it was only a dream, a paradise that I invented to make my exile bearable.", "اما برنگشتم و هرگز کابل را دوباره ندیدم، نه کابل کودکی‌ام، نه کابل خاطره‌ام، نه کابلی که پیش از جنگ‌ها وجود داشت و اغلب در سال‌های بعد حیران بوده‌ام آیا شهری که به یاد می‌آورم هرگز واقعاً وجود داشته، یا فقط رؤیایی بود، بهشتی که برای تحمل‌پذیر کردن تبعیدم اختراع کردم."),
        StoryParagraph("We traveled in the back of a truck, hidden beneath tarps and boxes, along with other refugees, and the journey was long and terrifying and I thought, more than once, that we would die, that the truck would be stopped, that the soldiers would find us, that we would be shot in a ditch and buried in a shallow grave and forgotten.", "در پشت یک کامیون سفر کردیم، زیر برزنت‌ها و جعبه‌ها پنهان، همراه با پناهندگان دیگر و سفر طولانی و ترسناک بود و بیش از یک بار فکر کردم می‌میریم، کامیون متوقف می‌شود، سربازها پیدایمان می‌کنند، در گودالی تیرباران می‌شویم و در گوری کم‌عمق دفن می‌شویم و فراموش می‌شویم."),
        StoryParagraph("We crossed the border into Pakistan, and from there, we made our way to the United States, to California, to a life that I could never have imagined and that I did not, at first, want, a life of strange customs and strange people and strange food and a language that I spoke but did not feel, a life in which I was free but not at home.", "از مرز به پاکستان گذشتیم و از آنجا، راهمان را به ایالات متحده، به کالیفرنیا، به زندگی‌ای که هرگز نمی‌توانستم تصورش کنم و در آغاز نمی‌خواستمش باز کردیم، زندگی‌ای از آداب عجیب و مردم عجیب و غذای عجیب و زبانی که صحبتش می‌کردم اما حسش نمی‌کردم، زندگی‌ای که در آن آزاد بودم اما در خانه نبودم."),
        StoryParagraph("Baba, who had been a wealthy man in Kabul, became a poor man in America; he worked at a gas station, at a flea market, at anything that would pay the bills; and he did this without complaint, though I could see, in his eyes, the pain of a man who had lost everything, the humiliation of a man who had once been respected and who was now anonymous.", "بابا، که در کابل مردی ثروتمند بوده، در آمریکا مردی فقیر شد؛ در پمپ بنزین کار کرد، در بازار مکاره، هر چیزی که صورتحساب‌ها را پرداخت کند؛ و این را بدون شکایت کرد، هرچند در چشمانش درد مردی که همه چیز را از دست داده بود می‌دیدم، تحقیر مردی که زمانی محترم بود و اکنون بی‌نام."),
        StoryParagraph("He did not thrive in America, as some immigrants do; he wilted; he aged; he became, slowly, a shadow of the man he had been, and I watched this, and I felt, for the first time in my life, something I had never felt before: love for my father, love uncomplicated by fear or resentment, love that came, at last, when it was almost too late.", "او در آمریکا شکوفا نشد، همانطور که بعضی مهاجران می‌شوند؛ پژمرد؛ پیر شد؛ آهسته سایه‌ای از مردی که بوده شد و این را تماشا کردم و برای اولین بار در زندگی‌ام، چیزی حس کردم که هرگز قبلاً حس نکرده بودم: عشق به پدرم، عشقی بی‌آمیخته با ترس یا دلخوری، عشقی که سرانجام آمد، وقتی تقریباً خیلی دیر شده بود."),
        StoryParagraph("I had spent my childhood resenting him, fearing him, longing for his approval; now, in America, I began to understand him, to see him not as a god but as a man, a man who had lost everything and who was doing his best to survive, a man who was, in his own way, heroic.", "کودکی‌ام را صرف دلخوری از او کرده بودم، ترس از او، آرزوی تأییدش؛ حالا، در آمریکا، شروع کردم به فهمیدنش، دیدنش نه همچون خدایی بلکه همچون مردی، مردی که همه چیز را از دست داده بود و تمام تلاشش را برای زنده ماندن می‌کرد، مردی که به شیوه خودش قهرمان بود."),
        StoryParagraph("I graduated from high school, then from college, and I became a writer, and I met a woman named Soraya, and I married her, and I thought, for a time, that I had left Afghanistan behind, that I had left my past behind, that I was, at last, free, that the boy who had failed in that alley had died, and that a new man, a better man, had taken his place.", "از دبیرستان فارغ‌التحصیل شدم، بعد از دانشگاه و نویسنده شدم و با زنی به نام ثریا آشنا شدم و با او ازدواج کردم و برای مدتی فکر کردم افغانستان را پشت سر گذاشته‌ام، گذشته‌ام را پشت سر گذاشته‌ام، سرانجام آزادم، پسری که در آن کوچه شکست خورده بود مرده و مردی نو، مردی بهتر، جایش را گرفته."),
        StoryParagraph("But I was not free, and I would never be free, because the past is not a place you can leave; it is a thing you carry with you; it is a weight that grows heavier with every year that you do not face it, with every lie that you tell to hide it, with every moment that you pretend it does not exist.", "اما آزاد نبودم و هرگز آزاد نمی‌شدم، چون گذشته جایی نیست که بتوانی ترکش کنی؛ چیزی است که با خود حمل می‌کنی؛ وزنی است که با هر سالی که با آن روبرو نمی‌شوی سنگین‌تر می‌شود، با هر دروغی که برای پنهانش می‌گویی، با هر لحظه‌ای که تظاهر می‌کنی وجود ندارد."),
        StoryParagraph("And then, one day, Rahim Khan called, and he told me that Hassan was dead, that he had been shot in the street, along with his wife, for defending their home, for defending the house where I had grown up, and I wept, and I wept for Hassan, and I wept for myself, and I wept for all the years I had wasted.", "و سپس، یک روز، رحیم‌خان زنگ زد و به من گفت حسن مرده است، در خیابان تیر خورده، همراه با همسرش، برای دفاع از خانه‌شان، برای دفاع از خانه‌ای که من در آن بزرگ شده بودم و گریستم و برای حسن گریستم و برای خودم گریستم و برای تمام سال‌هایی که هدر داده بودم گریستم."),
        StoryParagraph("I wept for all the years I had spent trying to forget what I should have been trying to remember, all the years I had spent running from what I should have been running toward, all the years I had spent pretending to be someone I was not, while the person I truly was waited, patiently, in the shadows, for me to acknowledge him.", "برای تمام سال‌هایی گریستم که صرف تلاش برای فراموش کردن چیزی کرده بودم که باید تلاش می‌کردم به یاد آورم، تمام سال‌هایی که صرف فرار از چیزی کرده بودم که باید به سمتش می‌دویدم، تمام سال‌هایی که صرف تظاهر به کسی کرده بودم که نیستم، در حالی که شخصی که واقعاً بودم، صبورانه، در سایه‌ها، منتظر بود تا به او اعتراف کنم."),
        StoryParagraph("'Come back,' Rahim Khan said. 'Come back to Afghanistan. There is something you must do.' And I knew, when I heard those words, that I had to go, that I had no choice, that this was the moment I had been waiting for, without knowing I was waiting for it, all my life.", "رحیم‌خان گفت: «بازگرد. به افغانستان بازگرد. کاری هست که باید انجام دهی.» و وقتی آن کلمات را شنیدم، می‌دانستم باید بروم، انتخابی نداشتم، این لحظه‌ای بود که تمام عمرم منتظرش بودم، بی‌آنکه بدانم منتظرش هستم."),
        StoryParagraph("For Rahim Khan told me something else, something that changed everything, something that made me understand, at last, who Hassan had truly been, and who I had truly been, and what our relationship had truly meant, all those years, when I thought I knew, when I thought I understood, when I thought I was the one who had the right to judge.", "زیرا رحیم‌خان چیز دیگری هم گفت، چیزی که همه چیز را تغییر داد، چیزی که باعث شد سرانجام بفهمم حسن واقعاً چه کسی بوده و من واقعاً چه کسی بوده‌ام و رابطه‌مان واقعاً چه معنایی داشته، تمام آن سال‌ها، وقتی فکر می‌کردم می‌دانم، وقتی فکر می‌کردم می‌فهمم، وقتی فکر می‌کردم من کسی هستم که حق قضاوت دارد."),
        StoryParagraph("'Hassan was your brother,' he said. 'Your half-brother. Baba's son.' And the world stopped, and everything I had believed about my life, about my father, about my past, was turned upside down, and I did not know, any longer, who I was or what I had been or what I was supposed to become.", "گفت: «حسن برادرت بود. برادر ناتنی‌ات. پسر بابا.» و جهان ایستاد و هر چیزی که درباره زندگی‌ام، درباره پدرم، درباره گذشته‌ام باور کرده بودم وارونه شد و دیگر نمی‌دانستم کی هستم یا چه بوده‌ام یا قرار بود چه شوم."),
        StoryParagraph("But I also knew, in that moment, that I had to go back, that I had to return to Kabul, that I had to find Hassan's son, my nephew, my blood, and that I had to do, at last, what I should have done thirty years ago, in that alley, when Hassan needed me and I did nothing.", "اما در آن لحظه هم می‌دانستم که باید برگردم، باید به کابل بازگردم، باید پسر حسن را پیدا کنم، برادرزاده‌ام را، خونم را و باید سرانجام کاری را بکنم که باید سی سال پیش، در آن کوچه، می‌کردم، وقتی حسن نیازم داشت و من هیچ نکردم."),
        StoryParagraph("And so I left my comfortable life in California, and I boarded a plane, and I flew to Pakistan, and from there, I crossed the border into Afghanistan, into the country of my birth, into the country of my shame, into the country that had haunted my dreams for thirty years.", "و اینگونه زندگی راحتم در کالیفرنیا را ترک کردم و سوار هواپیما شدم و به پاکستان پرواز کردم و از آنجا، از مرز به افغانستان گذشتم، به کشور تولدم، به کشور شرمم، به کشوری که سی سال رؤیاهایم را تسخیر کرده بود."),
        StoryParagraph("The Afghanistan I found was not the Afghanistan I remembered; it was a land scarred by decades of war, a land of rubble and ruins, a land where the Taliban ruled with an iron fist and where women were forbidden from leaving their homes, where music was banned and kites were forbidden and laughter was suspect.", "افغانستانی که یافتم همان افغانستانی نبود که به یاد می‌آوردم؛ سرزمینی بود زخم‌خورده از دهه‌ها جنگ، سرزمینی از آوار و ویرانه، سرزمینی که طالبان با مشت آهنین حکومت می‌کردند و زنان از ترک خانه‌هایشان منع می‌شدند، موسیقی ممنوع بود و بادبادک حرام و خنده مشکوک."),
        StoryParagraph("And yet, in the midst of all this destruction, I found something that I had not expected: I found a kind of courage, a kind of resilience, a kind of hope that no war could destroy, a kind of humanity that survived in the most inhuman conditions.", "و با این حال، در میان همه این نابودی، چیزی یافتم که انتظارش را نداشتم: نوعی شجاعت یافتم، نوعی تاب‌آوری، نوعی امیدی که هیچ جنگی نمی‌توانست نابودش کند، نوعی انسانیتی که در غیرانسانی‌ترین شرایط زنده می‌ماند."),
        StoryParagraph("I found it in Rahim Khan, who was dying but who was still kind, still wise, still the man I had known and loved as a child, still the man who believed in me, still the man who saw, in me, something worth saving.", "در رحیم‌خان یافتمش، که در حال مرگ بود اما هنوز مهربان، هنوز فرزانه، هنوز مردی که در کودکی شناخته و دوستش داشتم، هنوز مردی که به من باور داشت، هنوز مردی که در من چیزی می‌دید که ارزش نجات داشت."),
        StoryParagraph("I found it in Farid, the driver who took me through the dangerous roads of Afghanistan, a man who had lost his own family to the wars but who still fought, still hoped, still believed that his country could be saved, still believed that the sacrifice had been worth it.", "در فرید یافتمش، راننده‌ای که مرا از جاده‌های خطرناک افغانستان برد، مردی که خانواده‌اش را در جنگ‌ها از دست داده بود اما هنوز می‌جنگید، هنوز امید داشت، هنوز باور داشت کشورش می‌تواند نجات یابد، هنوز باور داشت فداکاری ارزشش را داشته."),
        StoryParagraph("And I found it, at last, in Sohrab, Hassan's son, my nephew, a boy who had been hurt as his father had been hurt, a boy who had lost everything, a boy who had, somehow, not lost hope, a boy whose eyes held the same light that had shone in his father's eyes, the light of a soul that refused to be extinguished.", "و سرانجام در سهراب یافتمش، پسر حسن، برادرزاده‌ام، پسری که آسیب دیده بود همانطور که پدرش آسیب دیده بود، پسری که همه چیز را از دست داده بود، پسری که به نوعی، امید را از دست نداده بود، پسری که چشمانش همان نوری را داشت که در چشمان پدرش می‌درخشید، نور روحی که امتناع می‌کرد خاموش شود."),
        StoryParagraph("And it was for Sohrab that I had come, it was for Sohrab that I had returned, it was for Sohrab that I would have to be brave, at last, as I had not been brave thirty years ago, in that alley, when Hassan needed me and I stood frozen and said nothing and let the world do its worst.", "و برای سهراب آمده بودم، برای سهراب بازگشته بودم، برای سهراب بود که باید سرانجام شجاع می‌شدم، همانطور که سی سال پیش شجاع نبودم، در آن کوچه، وقتی حسن نیازم داشت و من منجمد ایستادم و چیزی نگفتم و گذاشتم جهان بدترین کارش را بکند."),
        StoryParagraph("And so my journey to redemption began, in the ruins of Kabul, in the heart of a country I had loved and betrayed, in the company of a boy who had suffered more than any child should ever have to suffer, in the shadow of a past that I could not escape and did not, any longer, want to escape.", "و اینگونه سفرم به سوی رستگاری آغاز شد، در ویرانه‌های کابل، در قلب سرزمینی که دوستش داشته و به آن خیانت کرده بودم، در همراهی پسری که بیش از آنچه هر کودکی باید تحمل کند رنج کشیده بود، در سایه گذشته‌ای که نمی‌توانستم از آن بگریزم و دیگر، نمی‌خواستم بگریزم."),
        StoryParagraph("And I did not know, as I set out, whether I would succeed or fail, whether I would live or die, whether I would find redemption or only more guilt, whether the journey would heal me or destroy me.", "و وقتی راه افتادم نمی‌دانستم موفق می‌شوم یا شکست می‌خورم، زنده می‌مانم یا می‌میرم، رستگاری می‌یابم یا فقط گناه بیشتر، سفر شفایم می‌دهد یا نابودم می‌کند."),
        StoryParagraph("But I knew that I had to try, and that trying was the only thing that mattered, and that this — this attempt to be good — was the only answer to a life lived in shame, the only response to a betrayal that could not be undone, the only path to a peace that I had never known and that I was not sure I deserved.", "اما می‌دانستم باید تلاش کنم و تلاش کردن تنها چیزی بود که اهمیت داشت و این — این تلاش برای خوب بودن — تنها پاسخ به زندگی‌ای بود که در شرم گذرانده شده بود، تنها پاسخ به خیانتی که نمی‌شد جبرانش کرد، تنها راه به آرامشی که هرگز نشناخته بودم و مطمئن نبودم سزاوارش هستم."),
        StoryParagraph("And so the third part of my story ends, and the fourth part begins, the part about the journey, the part about the boy, the part about the redemption that I sought and that I was not sure I deserved.", "و اینگونه بخش سوم داستانم پایان می‌یابد و بخش چهارم آغاز می‌شود، بخشی درباره سفر، بخشی درباره پسر، بخشی درباره رستگاری‌ای که در جستجویش بودم و مطمئن نبودم سزاوارش هستم."),
        StoryParagraph("And the fourth part begins with a road, and with a car, and with a driver who did not trust me, and with a country that I did not recognize, and with a hope that I could not quite believe in but that I could not quite abandon.", "و بخش چهارم با جاده‌ای آغاز می‌شود و با ماشینی و با راننده‌ای که به من اعتماد نداشت و با سرزمینی که نمی‌شناختم و با امیدی که کاملاً نمی‌توانستم باورش کنم اما کاملاً هم نمی‌توانستم رهایش کنم."),
        StoryParagraph("For the journey to Sohrab was a journey into the heart of a country that had been destroyed, and into the heart of a man who had been destroyed, and into the heart of a hope that, against all evidence, refused to die.", "زیرا سفر به سوی سهراب سفری بود به قلب سرزمینی که نابود شده بود و به قلب مردی که نابود شده بود و به قلب امیدی که برخلاف همه شواهد، امتناع می‌کرد بمیرد."),
        StoryParagraph("And it was also a journey into the heart of my own darkness, into the alley where I had failed, into the memory that I had buried, into the shame that I had carried for thirty years, into the boy I had been and the man I had become and the man I still hoped to be.", "و همچنین سفری بود به قلب تاریکی خودم، به آن کوچه که در آن شکست خورده بودم، به خاطره‌ای که دفنش کرده بودم، به شرمی که سی سال حملش کرده بودم، به پسری که بوده بودم و مردی که شده بودم و مردی که هنوز امید داشتم باشم."),
        StoryParagraph("And so the journey began, and I did not know where it would lead, and I did not know what it would cost, and I did not know what I would find at the end, if anything at all.", "و اینگونه سفر آغاز شد و نمی‌دانستم به کجا می‌رسد و نمی‌دانستم چه هزینه‌ای دارد و نمی‌دانستم در پایان چه می‌یابم، اگر اصلاً چیزی بیابم."),
        StoryParagraph("But I knew that the boy was waiting, and that the promise had been made, and that I would keep it, this time, whatever the cost, because I had failed to keep it once before, and I could not, I would not, fail again.", "اما می‌دانستم پسر منتظر است و قول داده شده بود و این بار، هر هزینه‌ای هم داشت، نگهش می‌داشتم، چون یک بار قبلاً نگهش نداشته بودم و نمی‌توانستم، نمی‌خواستم، دوباره شکست بخورم."),
        StoryParagraph("And so I set out, in the winter of 2001, on the road to Kabul, on the road to Sohrab, on the road to the redemption that I had sought for thirty years and that I had never believed I would find.", "و اینگونه راه افتادم، در زمستان ۲۰۰۱، در جاده به کابل، در جاده به سهراب، در جاده به رستگاری‌ای که سی سال در جستجویش بودم و هرگز باور نداشتم می‌یابمش."),
        StoryParagraph("And the road, as roads always do, led me not only toward the future but also back into the past, back into the memories I had tried to bury, back into the alley, back into the silence, back into the moment when I became what I am today.", "و جاده، همانطور که جاده‌ها همیشه می‌کنند، مرا نه تنها به سوی آینده برد بلکه به گذشته هم، به خاطراتی که تلاش کرده بودم دفنشان کنم، به آن کوچه، به آن سکوت، به لحظه‌ای که آنچه امروز هستم شدم."),
        StoryParagraph("And on that road, in that car, with that driver, crossing that ruined landscape, I began, at last, to understand something that I had never understood before: that redemption is not a destination but a journey, and that the journey itself, however painful, is the answer.", "و در آن جاده، در آن ماشین، با آن راننده، در عبور از آن منظره ویران، شروع کردم، سرانجام، به فهمیدن چیزی که هرگز قبلاً نفهمیده بودم: که رستگاری نه مقصد است بلکه سفر و خود سفر، هر چقدر هم دردناک، پاسخ است."),
        StoryParagraph("And so the third part of my story ends, and the fourth part begins, and the road stretches ahead, and the boy waits, and the promise must be kept.", "و اینگونه بخش سوم داستانم پایان می‌یابد و بخش چهارم آغاز می‌شود و جاده پیش رو کشیده است و پسر منتظر است و قول باید نگه داشته شود."),
        StoryParagraph("For Hassan's son was waiting, and I was coming, at last, to save him, and in saving him, I would also, at last, save myself.", "زیرا پسر حسن منتظر بود و من می‌آمدم، سرانجام، تا نجاتش دهم و با نجات دادنش، سرانجام، خودم را هم نجات می‌دادم."),
        StoryParagraph("And that is the story of the fourth part, the story I must now tell.", "و این داستان بخش چهارم است، داستانی که باید اکنون بگویم.")
    )
)

// ─────────── فصل ۴: سهراب ───────────
private fun chapter4() = StoryChapter(
    number = 4, title = "Sohrab", titlePersian = "سهراب",
    paragraphs = listOf(
        StoryParagraph("I found Sohrab in an orphanage in Kabul, a place of sadness and neglect, a place where children who had lost everything had been gathered, a place where hope was a luxury that few could afford, a place where the future was not a promise but a threat.", "سهراب را در یتیم‌خانه‌ای در کابل یافتم، جایی از اندوه و بی‌توجهی، جایی که کودکانی که همه چیز را از دست داده بودند جمع شده بودند، جایی که امید تجملی بود که کمتر کسی می‌توانست از عهده‌اش برآید، جایی که آینده نه وعده بود بلکه تهدید."),
        StoryParagraph("He was a small boy, thin and quiet, with the same cleft lip that his father had had, the same scar that Baba had paid to have repaired, the same eyes that I had known and loved and betrayed, thirty years before, in a world that no longer existed, in a city that no longer existed, in a life that no longer existed.", "پسری کوچک بود، لاغر و ساکت، با همان لب‌شکری که پدرش داشته بود، همان جای زخمی که بابا هزینه درست کردنش را پرداخته بود، همان چشمانی که سی سال پیش شناخته و دوست داشته و به آن‌ها خیانت کرده بودم، در جهانی که دیگر وجود نداشت، در شهری که دیگر وجود نداشت، در زندگی‌ای که دیگر وجود نداشت."),
        StoryParagraph("He did not speak to me, not at first; he did not trust me, not at first; he had learned, in his short life, that adults could not be trusted, that they took what they wanted and left the rest, that promises were made to be broken, that love was a word that meant nothing.", "نخست با من صحبت نکرد؛ نخست به من اعتماد نکرد؛ در زندگی کوتاهش آموخته بود که به بزرگسالان نمی‌توان اعتماد کرد، که آن‌ها آنچه می‌خواهند را می‌گیرند و بقیه را رها می‌کنند، که قول‌ها برای شکستن داده می‌شوند، که عشق کلمه‌ای است که هیچ معنایی ندارد."),
        StoryParagraph("But I kept coming, day after day, and slowly, he began to open, as a flower opens to the sun, as a wound begins to heal, as a heart, long frozen, begins to thaw, as a boy who had known only cruelty began, at last, to believe that kindness might be real.", "اما هر روز می‌آمدم و آهسته، شروع به باز شدن کرد، همانطور که گلی به خورشید باز می‌شود، همانطور که زخمی شروع به التیام می‌کند، همانطور که قلبی، مدت‌ها یخ‌زده، شروع به ذوب شدن می‌کند، همانطور که پسری که تنها بی‌رحمی شناخته بود شروع کرد، سرانجام، به باور به اینکه مهربانی ممکن است واقعی باشد."),
        StoryParagraph("He told me about his father, about Hassan, about the life they had lived, about the happiness they had found, briefly, before the wars had taken everything, about the garden where they had grown vegetables, about the stories Hassan used to tell him at night, about the way Hassan would smile, even when there was nothing to smile about.", "از پدرش به من گفت، از حسن، از زندگی‌ای که داشته بودند، از خوشبختی‌ای که یافته بودند، به‌طور گذرا، پیش از آنکه جنگ‌ها همه چیز را بگیرند، از باغی که در آن سبزی می‌کاشتند، از داستان‌هایی که حسن شب‌ها برایش می‌گفت، از شیوه‌ای که حسن لبخند می‌زد، حتی وقتی چیزی برای لبخند زدن نبود."),
        StoryParagraph("'My father was the best man in the world,' he said, and his voice was quiet, and his eyes were far away, and I knew that he was seeing, in his mind, the man I had failed to protect, the man I had betrayed, the man who had been, all along, my brother.", "گفت: «پدرم بهترین مرد دنیا بود،» و صدایش آرام بود و چشمانش دور و می‌دانستم در ذهنش مردی را می‌دید که نتوانسته بودم محافظتش کنم، مردی که به او خیانت کرده بودم، مردی که تمام مدت، برادرم بوده بود."),
        StoryParagraph("'He used to tell me stories,' Sohrab said. 'Stories about heroes and adventures and faraway lands. And he would always say that one day, we would go to those lands together, that one day, we would be free.'", "سهراب گفت: «برایم داستان می‌گفت. داستان‌هایی درباره قهرمانان و ماجراجویی‌ها و سرزمین‌های دور. و همیشه می‌گفت یک روز، با هم به آن سرزمین‌ها می‌رویم، یک روز، آزاد می‌شویم.»"),
        StoryParagraph("'And did you believe him?' I asked, and my voice was barely a whisper.", "پرسیدم: «و باورش می‌کردی؟» و صدایم به‌سختی زمزمه بود."),
        StoryParagraph("'I believed everything he said,' Sohrab answered. 'He was my father. I believed him because he was the only person in the world who loved me.'", "سهراب پاسخ داد: «هر چیزی که می‌گفت باور می‌کردم. پدرم بود. باورش می‌کردم چون تنها کسی در دنیا بود که دوستم داشت.»"),
        StoryParagraph("And I wept, silently, because I knew what it meant to be loved by someone like Hassan, because I knew what it meant to betray that love, because I knew that I was, at that very moment, sitting in front of the son of the man I had betrayed, and that everything I did, from now on, would be an attempt to make up for what I had done.", "و بی‌صدا گریستم، چون می‌دانستم دوست داشته شدن توسط کسی مثل حسن یعنی چه، چون می‌دانستم خیانت به آن عشق یعنی چه، چون می‌دانستم در همان لحظه، مقابل پسر مردی نشسته‌ام که به او خیانت کرده بودم و هر کاری که از این پس می‌کردم، تلاشی بود برای جبران آنچه کرده بودم."),
        StoryParagraph("'Tell me about him,' I said, and Sohrab told me, and I listened, and I wept, and I did not hide my tears, because I had learned that hiding is what cowards do, and I was done, at last, with being a coward.", "گفتم: «از او برایم بگو.» و سهراب گفت و من گوش دادم و گریستم و اشک‌هایم را پنهان نکردم، چون آموخته بودم که پنهان کردن کار بزدل‌هاست و سرانجام، از بزدل بودن دست کشیده بودم."),
        StoryParagraph("And I told Sohrab about his father, about the boy I had known, about the kite runner who had chased fallen kites through the streets of Kabul, about the friend who had loved me even when I did not deserve to be loved, about the brother who had never known that he was my brother.", "و من برای سهراب از پدرش گفتم، از پسری که شناخته بودم، از بادبادک‌بازی که بادبادک‌های افتاده را در خیابان‌های کابل تعقیب می‌کرد، از دوستی که دوستم داشت حتی وقتی سزاوار دوست داشته شدن نبودم، از برادری که هرگز نمی‌دانست برادرم است."),
        StoryParagraph("I told him about the alley, about the winter of 1975, about the day I became what I am today, and I told him the truth, the whole truth, the truth that I had spent my life trying to hide, the truth that I had never spoken aloud, the truth that I had never fully admitted, even to myself.", "از آن کوچه برایش گفتم، از زمستان ۱۹۷۵، از روزی که آنچه امروز هستم شدم و حقیقت را به او گفتم، تمام حقیقت، حقیقتی که عمرم را صرف تلاش برای پنهانش کرده بودم، حقیقتی که هرگز بلند نگفته بودم، حقیقتی که هرگز کاملاً اعتراف نکرده بودم، حتی به خودم."),
        StoryParagraph("'I betrayed your father,' I said. 'I stood in that alley and watched him being hurt, and I did nothing. And then I lied about it, and I tried to forget it, and I spent thirty years running from what I had done.'", "گفتم: «به پدرت خیانت کردم. در آن کوچه ایستادم و تماشا کردم که دارد آسیب می‌بیند و هیچ نکردم. و بعد درباره‌اش دروغ گفتم و تلاش کردم فراموشش کنم و سی سال را صرف فرار از آنچه کرده بودم کردم.»"),
        StoryParagraph("Sohrab was silent for a long time, and I did not know what he was thinking, and I was afraid, more afraid than I had ever been, because I had just confessed the worst thing about myself to the son of the man I had wronged, and I did not know if he would forgive me, or if he would hate me, or if he would simply turn away.", "سهراب مدت طولانی ساکت بود و نمی‌دانستم چه فکر می‌کند و می‌ترسیدم، بیشتر از آنچه تا حالا ترسیده بودم، چون بدترین چیز درباره خودم را به پسر مردی اعتراف کرده بودم که به او ظلم کرده بودم و نمی‌دانستم می‌بخشد یا متنفر می‌شود یا فقط رو برمی‌گرداند."),
        StoryParagraph("'My father never spoke ill of you,' he said, at last. 'He never spoke of you at all, except to say that you were his friend, his best friend, the brother he had never had.'", "سرانجام گفت: «پدرم هرگز بدت را نگفت. هرگز از تو حرف نزد، جز برای گفتن اینکه دوستش بودی، بهترین دوستش، برادری که هرگز نداشته.»"),
        StoryParagraph("And I wept again, and I wept for Hassan, for his forgiveness, for his loyalty, for the love that I had never deserved and that he had given me anyway, freely, unconditionally, as only a brother can, as only a heart as pure as his could.", "و دوباره گریستم و برای حسن گریستم، برای بخشش او، برای وفاداری‌اش، برای عشقی که هرگز سزاوارش نبودم و او به هر حال به من داد، آزادانه، بی‌قید و شرط، همانطور که فقط برادری می‌تواند، همانطور که فقط قلبی به پاکی قلب او می‌تواند."),
        StoryParagraph("And then I told Sohrab that I had come to take him to America, to give him a home, to give him a life, to give him the chance that I had been given but had not deserved.", "و بعد به سهراب گفتم آمده‌ام او را به آمریکا ببرم، به او خانه‌ای بدهم، زندگی‌ای، فرصتی که به من داده شده بود اما سزاوارش نبودم."),
        StoryParagraph("He looked at me, and there was something in his eyes that I had never seen before, something that was neither hope nor despair, but something in between, something fragile, something precarious, something that could be destroyed by a single wrong word.", "نگاهم کرد و چیزی در چشمانش بود که هرگز قبلاً ندیده بودم، چیزی که نه امید بود نه ناامیدی، بلکه چیزی میان آن دو، چیزی شکننده، چیزی متزلزل، چیزی که با یک کلمه اشتباه نابود می‌شد."),
        StoryParagraph("'You promise?' he asked. 'You promise you will not abandon me?'", "پرسید: «قول می‌دهی؟ قول می‌دهی رهایم نمی‌کنی؟»"),
        StoryParagraph("'I promise,' I said, and I meant it, with all my heart, with all my soul, with everything I had, with everything I was, with everything I hoped to become.", "گفتم: «قول می‌دهم،» و منظورم بود، با تمام قلبم، با تمام روحم، با هر چیزی که داشتم، با هر چیزی که بودم، با هر چیزی که امید داشتم بشوم."),
        StoryParagraph("But promises, I had learned, were fragile things, easily made and easily broken, and I did not know, when I made that promise, how hard it would be to keep it, how many obstacles would rise in our path, how much pain awaited us both.", "اما قول‌ها، آموخته بودم، چیزهای شکننده‌ای بودند، راحت داده و راحت شکسته می‌شدند و وقتی آن قول را دادم، نمی‌دانستم نگه داشتنش چقدر سخت می‌بود، چند مانع در راهمان برمی‌خاست، چه دردهایی در انتظارمان بود."),
        StoryParagraph("The journey out of Afghanistan was dangerous, more dangerous than I had imagined, and there were moments when I thought we would not make it, moments when I thought I had failed, again, as I had failed before, moments when I thought that the boy would be taken from me as everything else had been taken.", "سفر بیرون از افغانستان خطرناک بود، خطرناک‌تر از آنچه تصور کرده بودم و لحظه‌هایی بود که فکر کردم نمی‌رسیم، لحظه‌هایی که فکر کردم دوباره شکست خورده‌ام، همانطور که قبلاً شکست خورده بودم، لحظه‌هایی که فکر کردم پسر از من گرفته می‌شود همانطور که هر چیز دیگری گرفته شده بود."),
        StoryParagraph("But we did make it, we did reach Pakistan, and from there, we boarded a plane, and we flew to America, and Sohrab, who had never seen a plane, who had never left his country, who had never known freedom, watched the clouds pass beneath us with a look of wonder that I will never forget.", "اما رسیدیم، به پاکستان رسیدیم و از آنجا، سوار هواپیما شدیم و به آمریکا پرواز کردیم و سهراب، که هرگز هواپیما ندیده بود، که هرگز کشورش را ترک نکرده بود، که هرگز آزادی را نشناخته بود، با نگاهی از شگفتی که هرگز فراموش نمی‌کنم تماشا کرد ابرها زیرمان می‌گذرند."),
        StoryParagraph("And I thought, as I watched him, that this is what redemption looks like: not a grand gesture, not a heroic act, but the simple, difficult work of keeping a promise, of being there, of not running away, of staying, of loving, of being present.", "و همانطور که تماشایش می‌کردم فکر کردم رستگاری اینگونه است: نه حرکتی بزرگ، نه عملی قهرمانانه، بلکه کار ساده و دشوارِ نگه داشتن یک قول، آنجا بودن، فرار نکردن، ماندن، عشق ورزیدن، حاضر بودن."),
        StoryParagraph("But redemption, I would learn, was not so simple, and the wounds that Sohrab carried were deeper than I had known, and the healing that I hoped for would not come easily, if it came at all, and the promise that I had made would be tested, again and again, in the months and years to come.", "اما رستگاری، می‌آموختم، اینقدر ساده نبود و زخم‌هایی که سهراب حمل می‌کرد عمیق‌تر از آن بود که می‌دانستم و التیامی که امید داشتم آسان نمی‌آمد، اگر اصلاً می‌آمد و قولی که داده بودم بارها و بارها در ماه‌ها و سال‌های بعد آزموده می‌شد."),
        StoryParagraph("And so the fourth part of my story ends, and the fifth part begins, the part about America, the part about the healing, the part about the promise that I would struggle, more than I had ever imagined, to keep.", "و اینگونه بخش چهارم داستانم پایان می‌یابد و بخش پنجم آغاز می‌شود، بخشی درباره آمریکا، بخشی درباره التیام، بخشی درباره قولی که برای نگه داشتنش بیشتر از آنچه تصور کرده بودم، تقلا می‌کردم."),
        StoryParagraph("For the fifth part is the hardest part, the part in which the healing does not come, the part in which the boy I had saved began, slowly, to slip away from me, the part in which I learned that redemption is not a single act but a lifelong process.", "زیرا بخش پنجم سخت‌ترین بخش است، بخشی که در آن التیام نمی‌آید، بخشی که در آن پسری که نجاتش داده بودم شروع کرد، آهسته، به لغزیدن از دستانم، بخشی که در آن آموختم رستگاری نه عملی واحد است بلکه فرایندی مادام‌العمر."),
        StoryParagraph("And so the fourth part of my story ends, and the fifth part begins, and the road continues, and the promise remains, and the boy waits, still, for me to prove that I am worthy of his trust.", "و اینگونه بخش چهارم داستانم پایان می‌یابد و بخش پنجم آغاز می‌شود و جاده ادامه دارد و قول باقی است و پسر منتظر است، هنوز، که ثابت کنم سزاوار اعتمادش هستم."),
        StoryParagraph("And I hope, I pray, I believe, that I will, at last, be worthy, that the promise will be kept, that the boy will be saved, and that in saving him, I will finally save myself.", "و امیدوارم، دعا می‌کنم، باور دارم که سرانجام، سزاوار می‌شوم، قول نگه داشته می‌شود، پسر نجات می‌یابد و با نجات دادنش، سرانجام خودم را نجات می‌دهم.")
    )
)
    // ─────────── فصل ۵: آمریکا ───────────
    private fun chapter5() = StoryChapter(
        number = 5, title = "America", titlePersian = "آمریکا",
        paragraphs = listOf(
            StoryParagraph("Sohrab came to America in the summer of 2002, and at first, everything seemed possible, seemed hopeful, seemed as if the past could be left behind and a new life could begin, as if the wounds could heal, as if the boy who had suffered so much could, at last, find peace.", "سهراب در تابستان ۲۰۰۲ به آمریکا آمد و در آغاز، همه چیز ممکن به نظر می‌رسید، پرامید، گویی گذشته را می‌شد پشت سر گذاشت و زندگی نو را می‌شد آغاز کرد، گویی زخم‌ها می‌توانستند التیام یابند، گویی پسری که اینقدر رنج کشیده بود می‌توانست، سرانجام، آرامش بیابد."),
            StoryParagraph("He was quiet, and sad, but he was also curious, and he began to learn English, and he began to make friends, and I thought, in my foolish optimism, that he was healing, that he was, at last, becoming a normal boy, that the horrors he had witnessed were fading, as all memories fade, with time.", "ساکت بود و غمگین، اما کنجکاو هم بود و شروع کرد به یادگیری انگلیسی و شروع کرد به پیدا کردن دوستان و در خوش‌بینی احمقانه‌ام فکر کردم دارد التیام می‌یابد، دارد سرانجام پسر عادی می‌شود، که وحشت‌هایی که شاهدشان بود محو می‌شدند، همانطور که همه خاطرات با زمان محو می‌شوند."),
            StoryParagraph("But I was wrong; the wounds were deeper than I had known, and they did not heal as I had hoped, and one day, without warning, without any sign that anything was wrong, Sohrab tried to take his own life.", "اما اشتباه می‌کردم؛ زخم‌ها عمیق‌تر از آن بود که می‌دانستم و همانطور که امید داشتم التیام نمی‌یافتند و یک روز، بی‌هشدار، بدون هیچ نشانه‌ای که چیزی اشتباه است، سهراب تلاش کرد جان خودش را بگیرد."),
            StoryParagraph("I found him in the bathtub, his wrists cut, the water red with blood, and I screamed, and I called the ambulance, and I held him, and I begged him to stay, and I promised him, again, that I would not abandon him.", "او را در وان حمام یافتم، مچ‌هایش بریده، آب سرخ از خون و جیغ زدم و آمبولانس خبر کردم و در آغوشش گرفتم و التماسش کردم بماند و دوباره قول دادم رهایش نمی‌کنم."),
            StoryParagraph("'I am sorry,' he said, and his voice was barely audible, and his eyes were empty, and I knew, in that moment, that I had failed him, that I had failed Hassan, that I had failed everyone who had ever trusted me.", "گفت: «متأسفم،» و صدایش به‌سختی شنیده می‌شد و چشمانش خالی بود و در آن لحظه دانستم که شکستش داده بودم، شکست داده بودم حسن را، شکست داده بودم هر کسی که هرگز به من اعتماد کرده بود."),
            StoryParagraph("He survived, but he was not the same after that; he was quieter, sadder, more distant, and I did not know how to reach him, and I felt, more than ever, the weight of my own failure, the weight of a debt that could never be repaid.", "زنده ماند، اما بعد از آن همان نبود؛ ساکت‌تر بود، غمگین‌تر، دورتر و نمی‌دانستم چطور به او برسم و بیش از همیشه، وزن شکست خودم را حس می‌کردم، وزن بدهی که هرگز نمی‌شد پرداختش کرد."),
            StoryParagraph("Soraya, my wife, helped; she was patient, and kind, and she loved Sohrab as if he were her own, and slowly, very slowly, he began to come back to us, to trust us, to believe, once more, that there were people in the world who would not hurt him.", "ثریا، همسرم، کمک کرد؛ صبور بود و مهربان و سهراب را دوست داشت گویی مال خودش است و آهسته، بسیار آهسته، شروع کرد به بازگشت به سمت ما، اعتماد به ما، باور، یک بار دیگر، به اینکه در جهان مردمی هستند که آسیبش نمی‌زنند."),
            StoryParagraph("But the healing was not complete, and I did not know if it ever would be, and I did not know if I had done enough, if I had been enough, if I had, at last, kept my promise to Hassan, to Sohrab, to myself.", "اما التیام کامل نبود و نمی‌دانستم آیا هرگز می‌شود و نمی‌دانستم آیا به‌اندازه کافی کرده‌ام، آیا کافی بوده‌ام، آیا سرانجام قولم را به حسن، به سهراب، به خودم نگه داشته بودم."),
            StoryParagraph("And then, one day, I took Sohrab to a park, to fly a kite, and something happened, something small and simple and yet profound, something that I would remember for the rest of my life.", "و سپس، یک روز، سهراب را به پارکی بردم تا بادبادک بپراند و چیزی اتفاق افتاد، چیزی کوچک و ساده و با این حال عمیق، چیزی که تا آخر عمر به یاد می‌آوردم."),
            StoryParagraph("I bought a kite, and I showed him how to fly it, and I told him about his father, about how Hassan had been the greatest kite runner in Kabul, about how he had run after kites without ever losing one, about how he had always known where a kite would land before it had even begun to fall.", "بادبادکی خریدم و نشانش دادم چطور بپراندش و از پدرش گفتم، از اینکه حسن بزرگ‌ترین بادبادک‌باز کابل بوده، از اینکه بادبادک‌ها را بی‌آنکه یکی را از دست بدهد تعقیب می‌کرد، از اینکه همیشه می‌دانست بادبادکی پیش از آنکه حتی شروع به افتادن کرده باشد کجا فرود می‌آید."),
            StoryParagraph("'Do you want to try?' I asked, and he nodded, and I handed him the string, and he flew the kite, and for a moment, just a moment, he smiled, and in that smile, I saw Hassan.", "پرسیدم: «می‌خواهی امتحان کنی؟» و سر تکان داد و رشته را به دستش دادم و بادبادک را پراند و برای لحظه‌ای، فقط لحظه‌ای، لبخند زد و در آن لبخند، حسن را دیدم."),
            StoryParagraph("And in that smile, I saw Hassan, and I saw the boy I had been, and I saw all the years that had been lost, and I saw, at last, that redemption was not a destination but a journey, not an ending but a beginning, not a moment but a lifetime.", "و در آن لبخند، حسن را دیدم و پسری که بوده بودم را دیدم و تمام سال‌های از دست رفته را دیدم و سرانجام دیدم رستگاری نه مقصد است بلکه سفر، نه پایانی بلکه آغازی، نه لحظه‌ای بلکه عمری."),
            StoryParagraph("We flew the kite together, Sohrab and I, and I told him stories, as I had once told his father stories, and he listened, as his father had once listened, and I felt, in that moment, a connection to Hassan that I had not felt in thirty years.", "با هم بادبادک پراندیم، سهراب و من و برایش داستان گفتم، همانطور که زمانی برای پدرش داستان گفته بودم و او گوش داد، همانطور که پدرش زمانی گوش داده بود و در آن لحظه، پیوندی با حسن حس کردم که سی سال حس نکرده بودم."),
            StoryParagraph("And I understood, at last, that Hassan was not dead, not really, that he lived on in his son, in his smile, in his kindness, in the way he looked at the world with wonder and trust, in the way he loved, without reservation, without fear, as his father had loved.", "و سرانجام فهمیدم که حسن نمرده بود، نه واقعاً، که در پسرش زندگی می‌کرد، در لبخندش، در مهربانی‌اش، در شیوه‌ای که با شگفتی و اعتماد به جهان نگاه می‌کرد، در شیوه‌ای که دوست می‌داشت، بدون تردید، بدون ترس، همانطور که پدرش دوست می‌داشت."),
            StoryParagraph("And I understood, also, that I would spend the rest of my life trying to be worthy of that love, trying to be the man Hassan believed I could be, trying to be, at last, good again.", "و همچنین فهمیدم که باقی عمرم را صرف تلاش می‌کردم تا سزاوار آن عشق باشم، تلاش می‌کردم مردی باشم که حسن باور داشت می‌توانم باشم، تلاش می‌کردم، سرانجام، دوباره خوب باشم."),
            StoryParagraph("The years passed, as years do, and Sohrab grew, and he became, slowly, a young man, a young man who was quiet and thoughtful and kind, a young man who carried within him the memory of his father, the memory of Afghanistan, the memory of everything he had lost.", "سال‌ها گذشتند، همانطور که سال‌ها می‌گذرند و سهراب بزرگ شد و آهسته، مرد جوانی شد، مرد جوانی ساکت و متفکر و مهربان، مرد جوانی که در درونش خاطره پدرش را حمل می‌کرد، خاطره افغانستان را، خاطره هر چیزی که از دست داده بود."),
            StoryParagraph("And I grew older too, and I wrote books, and I taught at universities, and I became, in some small way, successful, but none of this mattered as much as the boy who had become my son, the boy I had saved, the boy who had saved me.", "و من هم پیرتر شدم و کتاب نوشتم و در دانشگاه‌ها درس دادم و به نوعی کوچک، موفق شدم، اما هیچ‌کدام از این‌ها به‌اندازه پسری که پسرم شده بود اهمیت نداشت، پسری که نجاتش داده بودم، پسری که مرا نجات داده بود."),
            StoryParagraph("And yet, the guilt never left me, not fully, not completely, for guilt, I had learned, is not a thing that can be erased; it is a thing that must be carried, and the only question is how you carry it, whether you let it destroy you or whether you use it to become better.", "و با این حال، گناه هرگز ترکم نکرد، نه کاملاً، نه به‌طور کامل، چون گناه، آموخته بودم، چیزی نیست که بتوان پاکش کرد؛ چیزی است که باید حمل شود و تنها پرسش این است که چگونه حملش می‌کنی، می‌گذاری نابودت کند یا از آن برای بهتر شدن استفاده می‌کنی."),
            StoryParagraph("I used it to become better; I used it to become the kind of man who would not stand by and watch suffering; I used it to become the kind of man who would act, who would speak, who would not be silent, who would not be a coward.", "از آن برای بهتر شدن استفاده کردم؛ از آن برای شدن نوعی از مرد استفاده کردم که کنار نمی‌ایستد و تماشا نمی‌کند رنج را؛ از آن برای شدن نوعی از مرد استفاده کردم که عمل می‌کند، صحبت می‌کند، سکوت نمی‌کند، بزدل نمی‌شود."),
            StoryParagraph("And I used it to teach Sohrab what I had learned the hard way, what Hassan had taught me without ever saying it, what the alley had taught me in a single, terrible moment: that courage is not the absence of fear, but the willingness to act in spite of it.", "و از آن استفاده کردم تا به سهراب چیزی بیاموزم که به سختی آموخته بودم، چیزی که حسن بی‌آنکه هرگز بگویدش به من آموخته بود، چیزی که آن کوچه در لحظه‌ای واحد و هولناک به من آموخته بود: که شجاعت نبود ترس نیست، بلکه آمادگی عمل کردن به رغم آن است."),
            StoryParagraph("And I used it to teach him, also, what it means to forgive, what it means to let go of the past, what it means to live, not in the shadow of what was done to you, but in the light of what you choose to do.", "و از آن استفاده کردم تا به او بیاموزم، همچنین، بخشیدن یعنی چه، رها کردن گذشته یعنی چه، زندگی کردن یعنی چه، نه در سایه آنچه به تو کرده‌اند، بلکه در نور آنچه انتخاب می‌کنی بکنی."),
            StoryParagraph("For that, at last, was the lesson of my life, the lesson I had learned in the alley, the lesson I had spent thirty years trying to understand, the lesson I would spend the rest of my life trying to teach.", "زیرا آن، سرانجام، درس زندگی‌ام بود، درسی که در آن کوچه آموخته بودم، درسی که سی سال صرف تلاش برای فهمیدنش کرده بودم، درسی که باقی عمرم صرف تلاش برای آموزشش می‌کردم."),
            StoryParagraph("That the past cannot be changed, but the future can; that the wrongs we commit cannot be undone, but they can be atoned for; that the wounds we carry cannot be erased, but they can be transformed into something beautiful.", "که گذشته را نمی‌شود تغییر داد، اما آینده را می‌شود؛ که خطاهایی که مرتکب می‌شویم را نمی‌شود جبران کرد، اما می‌شود برایشان کفاره داد؛ که زخم‌هایی که حمل می‌کنیم را نمی‌شود پاک کرد، اما می‌شود به چیزی زیبا تبدیلشان کرد."),
            StoryParagraph("And so the fifth part of my story ends, and the sixth part begins, the part about the meaning, the part about what it all meant, if it meant anything at all.", "و اینگونه بخش پنجم داستانم پایان می‌یابد و بخش ششم آغاز می‌شود، بخشی درباره معنا، بخشی درباره اینکه همه‌اش چه معنایی داشت، اگر اصلاً معنایی داشت."),
            StoryParagraph("For I have asked myself, many times, what the meaning of my life has been, what the meaning of Hassan's death has been, what the meaning of Sohrab's suffering has been, and I have not always found an answer.", "زیرا بارها از خودم پرسیده‌ام معنای زندگی‌ام چه بوده، معنای مرگ حسن چه بوده، معنای رنج سهراب چه بوده و همیشه پاسخی نیافته‌ام."),
            StoryParagraph("But I have found something else, something that may be more important than an answer: I have found a way to live, a way to be, a way to move forward, a way to carry the weight of the past without being crushed by it.", "اما چیز دیگری یافته‌ام، چیزی که شاید مهم‌تر از پاسخ باشد: راهی برای زندگی کردن یافته‌ام، راهی برای بودن، راهی برای حرکت به جلو، راهی برای حمل کردن وزن گذشته بدون خرد شدن زیرش."),
            StoryParagraph("And I have found that way in the same place Hassan found it, in the same place Sohrab found it, in the same place that all who suffer find it, if they are lucky: in love, in kindness, in the simple act of being there for another human being.", "و آن راه را همان جایی یافته‌ام که حسن یافتش، همان جایی که سهراب یافتش، همان جایی که همه رنج‌کشیدگان یافتندش، اگر خوش‌شانس باشند: در عشق، در مهربانی، در عمل ساده حاضر بودن برای انسان دیگری."),
            StoryParagraph("And so the fifth part of my story ends, and the sixth part begins, and I continue to write, continue to teach, continue to live, continue to try to be good again, as I will try, until my last breath, to be good again.", "و اینگونه بخش پنجم داستانم پایان می‌یابد و بخش ششم آغاز می‌شود و به نوشتن ادامه می‌دهم، به آموزش دادن، به زندگی کردن، به تلاش برای دوباره خوب بودن، همانطور که تا آخرین نفسم تلاش می‌کنم، دوباره خوب باشم."),
            StoryParagraph("For Hassan, for Sohrab, for myself, for everyone who has ever failed and who has ever tried to make up for that failure.", "برای حسن، برای سهراب، برای خودم، برای هر کسی که هرگز شکست خورده و هرگز تلاش کرده برای آن شکست جبران کند.")
        )
    )

    // ─────────── فصل ۶: معنا ───────────
    private fun chapter6() = StoryChapter(
        number = 6, title = "The Meaning", titlePersian = "معنا",
        paragraphs = listOf(
            StoryParagraph("The Kite Runner, published in 2003, is one of the most powerful novels of the twenty-first century, and its meaning deepens with every reading, as all great novels do, revealing new layers of significance with each return.", "بادبادک‌باز، منتشرشده در ۲۰۰۳، یکی از قدرتمندترین رمان‌های قرن بیست و یکم است و معنایش با هر خوانش عمیق‌تر می‌شود، همانطور که همه رمان‌های بزرگ می‌کنند، با هر بازگشت لایه‌های جدیدی از اهمیت را آشکار می‌کند."),
            StoryParagraph("It is, on the surface, a novel about Afghanistan, about a country torn apart by decades of war, about a people who suffered more than any people should have to suffer, about a land that was once beautiful and that was destroyed by forces beyond its control.", "در سطح، رمانی است درباره افغانستان، درباره سرزمینی که توسط دهه‌ها جنگ تکه‌تکه شده، درباره مردمی که بیش از آنچه هر مردمی باید تحمل کند رنج کشیده‌اند، درباره سرزمینی که زمانی زیبا بود و توسط نیروهایی فراتر از کنترلش نابود شد."),
            StoryParagraph("But it is, at a deeper level, a novel about guilt and redemption, about the wounds we carry, about the long, painful process of learning to be good again, about the journey that every human being must undertake, whether they know it or not.", "اما در سطح عمیق‌تر، رمانی است درباره گناه و رستگاری، درباره زخم‌هایی که حمل می‌کنیم، درباره فرایند طولانی و دردناک یادگیری دوباره خوب بودن، درباره سفری که هر انسانی باید بپیماید، خواه بداند خواه نداند."),
            StoryParagraph("Amir, the protagonist, is not a hero in the conventional sense; he is a coward, a liar, a boy who failed his friend, a man who spent his life running from his past, and yet, in the end, he becomes something else, something greater, something that we can all aspire to be.", "امیر، شخصیت اصلی، قهرمانی به معنای متعارف نیست؛ بزدلی است، دروغگویی، پسری که دوستش را شکست داد، مردی که عمرش را صرف فرار از گذشته‌اش کرد و با این حال، در پایان، به چیز دیگری تبدیل می‌شود، چیزی بزرگ‌تر، چیزی که همه ما می‌توانیم آرزوی بودنش را داشته باشیم."),
            StoryParagraph("For Amir is us; Amir is every human being who has ever failed, who has ever betrayed, who has ever stood by and watched while evil was done, and who has ever wondered, in the dark hours of the night, whether they could ever be forgiven.", "زیرا امیر ماست؛ امیر هر انسانی است که هرگز شکست خورده، که هرگز خیانت کرده، که هرگز ایستاده و تماشا کرده در حالی که شرارت انجام می‌شود و هرگز در ساعات تاریک شب حیران شده که آیا می‌تواند بخشیده شود."),
            StoryParagraph("And Hassan is what we should aspire to be; Hassan is the friend who forgives, the brother who loves unconditionally, the servant who is more noble than the master, the victim who refuses to become a victimizer.", "و حسن همان چیزی است که باید آرزوی بودنش را داشته باشیم؛ حسن دوستی است که می‌بخشد، برادری که بی‌قید و شرط دوست می‌دارد، خدمتکاری که از ارباب نجیب‌تر است، قربانی‌ای که امتناع می‌کند قربانی‌گر شود."),
            StoryParagraph("And Baba is the secret that we all carry; Baba is the father who is not what he seems, the man who judges others while hiding his own sins, the patriarch whose love is complicated and whose approval we spend our lives trying to earn.", "و بابا رازی است که همه ما حمل می‌کنیم؛ بابا پدری است که آنچه به نظر می‌رسد نیست، مردی که دیگران را قضاوت می‌کند در حالی که گناهان خودش را پنهان می‌کند، پدرسالاری که عشقش پیچیده است و تأییدش را تمام عمر صرف تلاش برای کسبش می‌کنیم."),
            StoryParagraph("And Sohrab is the hope; Sohrab is the child who survives, the boy who suffers but who does not break, the young man who learns, slowly, to trust again, to love again, to live again.", "و سهراب امید است؛ سهراب کودکی است که زنده می‌ماند، پسری که رنج می‌کشد اما نمی‌شکند، مرد جوانی که آهسته یاد می‌گیرد دوباره اعتماد کند، دوباره عشق بورزد، دوباره زندگی کند."),
            StoryParagraph("The novel is about Afghanistan, yes, but it is also about America, and about the immigrant experience, about what it means to leave your homeland and to try to build a new life in a new country, about the way the past follows you, wherever you go.", "رمان درباره افغانستان است، بله، اما همچنین درباره آمریکا است، درباره تجربه مهاجرت، درباره اینکه ترک کردن سرزمین مادری و تلاش برای ساختن زندگی نو در کشور جدید یعنی چه، درباره شیوه‌ای که گذشته هر جا می‌روی تعقیبت می‌کند."),
            StoryParagraph("The novel is about fathers and sons, about the love that is never spoken, about the approval that is never given, about the words that are never said until it is too late.", "رمان درباره پدران و پسران است، درباره عشقی که هرگز گفته نمی‌شود، درباره تأییدی که هرگز داده نمی‌شود، درباره کلماتی که هرگز گفته نمی‌شوند تا وقتی خیلی دیر شده."),
            StoryParagraph("The novel is about betrayal, about the moment when we choose ourselves over others, about the moment when we let fear win, about the moment when we become, in a single instant, what we will spend the rest of our lives trying to atone for.", "رمان درباره خیانت است، درباره لحظه‌ای که خودمان را بر دیگران ترجیح می‌دهیم، درباره لحظه‌ای که می‌گذاریم ترس ببرد، درباره لحظه‌ای که در لحظه‌ای واحد، به آنچه باقی عمرمان صرف تلاش برای کفاره‌اش می‌کنیم تبدیل می‌شویم."),
            StoryParagraph("And the novel is about redemption, about the possibility that we can become better than we were, that we can atone for what we have done, that we can, at last, be good again.", "و رمان درباره رستگاری است، درباره امکانی که می‌توانیم بهتر از آنچه بودیم شویم، که می‌توانیم برای آنچه کرده‌ایم کفاره دهیم، که می‌توانیم، سرانجام، دوباره خوب باشیم."),
            StoryParagraph("The kite is the central symbol of the novel, and its meaning is multiple: it is childhood, it is innocence, it is freedom, it is hope, it is the thing that we chase, and the thing that we lose, and the thing that we try, our whole lives, to catch again.", "بادبادک نماد مرکزی رمان است و معنایش چندگانه است: کودکی است، معصومیت است، آزادی است، امید است، چیزی است که تعقیبش می‌کنیم و چیزی که از دستش می‌دهیم و چیزی که تمام عمرمان تلاش می‌کنیم دوباره بگیریمش."),
            StoryParagraph("The kite is also the moment of betrayal, the moment when Amir watched Hassan being hurt, the moment that defined him, the moment he spent thirty years trying to overcome.", "بادبادک همچنین لحظه خیانت است، لحظه‌ای که امیر تماشا کرد حسن آسیب می‌بیند، لحظه‌ای که او را تعریف کرد، لحظه‌ای که سی سال صرف تلاش برای غلبه بر آن کرد."),
            StoryParagraph("And the kite is also the moment of redemption, the moment when Amir flew a kite with Sohrab, the moment when he finally understood that redemption was not a thing you achieved but a thing you did, again and again, for the rest of your life.", "و بادبادک همچنین لحظه رستگاری است، لحظه‌ای که امیر با سهراب بادبادک پراند، لحظه‌ای که سرانجام فهمید رستگاری چیزی نیست که به آن برسی بلکه چیزی است که انجامش می‌دهی، بارها و بارها، برای باقی عمرت."),
            StoryParagraph("For redemption is not a single act but a practice, not a moment but a way of life, not a destination but a path, and the only way to walk that path is to keep walking, one step at a time, one day at a time.", "زیرا رستگاری عملی واحد نیست بلکه تمرینی است، لحظه‌ای نیست بلکه شیوه‌ای از زندگی است، مقصدی نیست بلکه مسیری است و تنها راه پیمودن آن مسیر این است که به راه رفتن ادامه دهی، یک قدم در یک زمان، یک روز در یک زمان."),
            StoryParagraph("The novel asks us: what would you do if you were in Amir's place? Would you stand by and watch, or would you act? Would you be a coward, or would you be brave? Would you spend your life running from your past, or would you turn and face it?", "رمان از ما می‌پرسد: اگر جای امیر بودی چه می‌کردی؟ کنار می‌ایستادی و تماشا می‌کردی یا عمل می‌کردی؟ بزدل می‌بودی یا شجاع؟ عمرت را صرف فرار از گذشته‌ات می‌کردی یا برمی‌گشتی و با آن روبرو می‌شدی؟"),
            StoryParagraph("The novel does not provide easy answers, because there are no easy answers; it simply tells a story, a story that we can learn from, a story that can change us, a story that can make us, if we let it, better people.", "رمان پاسخ‌های آسان ارائه نمی‌دهد، چون پاسخ آسان وجود ندارد؛ فقط داستانی تعریف می‌کند، داستانی که می‌توانیم از آن بیاموزیم، داستانی که می‌تواند تغییرمان دهد، داستانی که می‌تواند ما را، اگر بگذاریم، انسان‌های بهتری کند."),
            StoryParagraph("And this, perhaps, is the true meaning of the novel: that we are all capable of both cowardice and courage, of both betrayal and loyalty, of both cruelty and kindness, and that the choice is ours, always ours, every day, every moment.", "و این، شاید، معنای واقعی رمان است: که همه ما قادر به هم بزدلی و هم شجاعتیم، هم خیانت و هم وفاداری، هم بی‌رحمی و هم مهربانی و انتخاب مال ماست، همیشه مال ماست، هر روز، هر لحظه."),
            StoryParagraph("Amir made the wrong choice, once, when he was twelve years old, and he spent the rest of his life trying to make up for it, and in the end, he did.", "امیر انتخاب اشتباه کرد، یک بار، وقتی دوازده ساله بود و باقی عمرش صرف تلاش برای جبرانش کرد و در پایان، موفق شد."),
            StoryParagraph("But his redemption did not come easily, and it did not come all at once, and it did not come without cost; it came slowly, painfully, over decades, through loss and grief and suffering, through failure and failure and failure, until, at last, something changed.", "اما رستگاری‌اش آسان نیامد و یکجا نیامد و بدون هزینه نیامد؛ آهسته آمد، دردناک، در طول دهه‌ها، از میان فقدان و اندوه و رنج، از میان شکست و شکست و شکست، تا اینکه سرانجام، چیزی تغییر کرد."),
            StoryParagraph("And that, perhaps, is the most important lesson of the novel: that redemption is possible, but it is never easy, and it is never complete, and it is never, ever, something we can achieve alone.", "و این، شاید، مهم‌ترین درس رمان است: که رستگاری ممکن است، اما هرگز آسان نیست و هرگز کامل نیست و هرگز، هرگز، چیزی نیست که بتوانیم تنهایی به آن برسیم."),
            StoryParagraph("We need others, as Amir needed Hassan, as Amir needed Sohrab, as Amir needed Soraya, as Amir needed Rahim Khan; we need them to forgive us, to teach us, to show us the way, to remind us, when we forget, that we are worth saving.", "ما به دیگران نیاز داریم، همانطور که امیر به حسن نیاز داشت، همانطور که امیر به سهراب نیاز داشت، همانطور که امیر به ثریا نیاز داشت، همانطور که امیر به رحیم‌خان نیاز داشت؛ ما به آن‌ها نیاز داریم تا ببخشندمان، بیاموزندمان، راه را نشانمان دهند، یادمان بیاورند، وقتی فراموش می‌کنیم، که ارزش نجات یافتن داریم."),
            StoryParagraph("And this, at last, is what the novel means to me: that we are all broken, all flawed, all guilty of something; and that we are all, also, capable of being healed, of being forgiven, of being, at last, good again.", "و این، سرانجام، همان چیزی است که رمان برایم معنا می‌کند: که همه‌مان شکسته‌ایم، همه‌مان معیوبیم، همه‌مان به چیزی گناهکاریم؛ و همه‌مان، همچنین، قادر به شفا یافتنیم، به بخشیده شدن، به بودن، سرانجام، دوباره خوب."),
            StoryParagraph("The Kite Runner is not a comfortable novel; it does not let us off the hook; it does not allow us to forget the ways in which we, too, have failed, the ways in which we, too, have betrayed, the ways in which we, too, have stood by and done nothing.", "بادبادک‌باز رمان راحتی نیست؛ ما را رها نمی‌کند؛ اجازه نمی‌دهد فراموش کنیم شیوه‌هایی که ما هم شکست خورده‌ایم، شیوه‌هایی که ما هم خیانت کرده‌ایم، شیوه‌هایی که ما هم ایستاده‌ایم و هیچ نکرده‌ایم."),
            StoryParagraph("But it is also a hopeful novel; it tells us that no matter how far we have fallen, no matter how badly we have failed, no matter how much we have betrayed, there is still a way to be good again.", "اما رمان امیدوارکننده‌ای هم است؛ به ما می‌گوید هر چقدر هم افتاده باشیم، هر چقدر هم بد شکست خورده باشیم، هر چقدر هم خیانت کرده باشیم، هنوز راهی برای دوباره خوب بودن هست."),
            StoryParagraph("And that way is simple, though it is not easy: it is to turn around, to face the past, to accept what we have done, and to begin, one small act at a time, to make it right.", "و آن راه ساده است، هرچند آسان نیست: برگشتن، رویارویی با گذشته، پذیرش آنچه کرده‌ایم و شروع کردن، یک عمل کوچک در یک زمان، به درست کردنش."),
            StoryParagraph("For that is what Amir did; that is what we all must do, if we are to become the people we want to be, the people we were meant to be, the people who can, at last, be good again.", "زیرا این همان کاری است که امیر کرد؛ این همان کاری است که همه‌مان باید بکنیم، اگر می‌خواهیم کسانی شویم که می‌خواهیم باشیم، کسانی که باید باشیم، کسانی که می‌توانند، سرانجام، دوباره خوب باشند."),
            StoryParagraph("And so the sixth part of my story ends, and the seventh part begins, the part about the last chapter, the part about what came after, the part about the life I have lived, since, in the shadow of that alley and in the light of my atonement.", "و اینگونه بخش ششم داستانم پایان می‌یابد و بخش هفتم آغاز می‌شود، بخشی درباره آخرین فصل، بخشی درباره آنچه پس از آن آمد، بخشی درباره زندگی‌ای که از آن زمان زندگی کرده‌ام، در سایه آن کوچه و در نور کفاره‌ام."),
            StoryParagraph("For my story does not end with Hassan, or with Sohrab, or with the kite that we flew together in that park in California; it ends, if it ends at all, with the simple truth that I have tried to live by, ever since: that there is a way to be good again.", "زیرا داستان من با حسن پایان نمی‌یابد، یا با سهراب، یا با بادبادکی که با هم در آن پارک در کالیفرنیا پراندیم؛ با حقیقت ساده‌ای پایان می‌یابد، اگر اصلاً پایان یابد، که از آن زمان تلاش کرده‌ام بر اساسش زندگی کنم: که راهی برای دوباره خوب بودن هست."),
            StoryParagraph("And that truth is enough; that truth has always been enough; that truth is, at last, all I need.", "و آن حقیقت کافی است؛ آن حقیقت همیشه کافی بوده؛ آن حقیقت، سرانجام، تمام چیزی است که نیاز دارم.")
        )
    )

    // ─────────── فصل ۷: پایان ───────────
    private fun chapter7() = StoryChapter(
        number = 7, title = "The End", titlePersian = "پایان",
        paragraphs = listOf(
            StoryParagraph("And so I have come to the end of my story, or rather to the place where my story, for now, must rest, because all stories must end, and this one, like all the others, has reached the moment where it must be given over to silence.", "و اینگونه به پایان داستانم رسیده‌ام، یا بهتر، به جایی که داستانم، برای اکنون، باید بیاساید، چون همه داستان‌ها باید تمام شوند و این یکی، همچون همه دیگران، به لحظه‌ای رسیده که باید به سکوت سپرده شود."),
            StoryParagraph("But this story, my story, does not end the way most stories end, with a resolution, with a conclusion, with everything wrapped up neatly and tied with a bow; it ends the way life ends, in the middle, with questions unanswered, with wounds still healing, with the future uncertain.", "اما این داستان، داستان من، همانطور که بیشتر داستان‌ها تمام می‌شوند پایان نمی‌یابد، با حل شدن، با نتیجه‌گیری، با همه چیز مرتب بسته‌بندی شدن و با روبان بسته شدن؛ همانطور که زندگی تمام می‌شود پایان می‌یابد، در وسط، با پرسش‌های بی‌پاسخ، با زخم‌های در حال التیام، با آینده‌ای نامعلوم."),
            StoryParagraph("I have told you about the alley, about Hassan, about my betrayal; I have told you about the escape from Kabul, about the years in America, about the journey back; I have told you about Sohrab, about the promise, about the kite.", "از کوچه برایتان گفتم، از حسن، از خیانتم؛ از فرار از کابل گفتم، از سال‌های آمریکا، از سفر بازگشت؛ از سهراب گفتم، از قول، از بادبادک."),
            StoryParagraph("And now, at the end of it all, I want to tell you one more thing, the thing that I have learned, the thing that I know, the thing that I would give everything I have to pass on to you.", "و اکنون، در پایان همه‌اش، می‌خواهم یک چیز دیگر بگویم، چیزی که آموخته‌ام، چیزی که می‌دانم، چیزی که هر چه دارم می‌دادم تا به شما منتقلش کنم."),
            StoryParagraph("I want to tell you that the past is not a burden; the past is a teacher. I want to tell you that failure is not the end; failure is a beginning. I want to tell you that guilt is not a punishment; guilt is an invitation.", "می‌خواهم بگویم گذشته بار نیست؛ گذشته معلم است. می‌خواهم بگویم شکست پایان نیست؛ شکست آغاز است. می‌خواهم بگویم گناه مجازات نیست؛ گناه دعوتی است."),
            StoryParagraph("An invitation to change, to grow, to become better; an invitation to look at what you have done and to choose, in that moment, to become the person who would not do it again.", "دعوتی به تغییر، به رشد، به بهتر شدن؛ دعوتی به نگاه کردن به آنچه کرده‌ای و انتخاب کردن، در آن لحظه، شدن کسی که دیگر تکرارش نمی‌کند."),
            StoryParagraph("I want to tell you that redemption is not a thing that can be earned; it is a gift, given to those who ask, given to those who try, given to those who never stop, no matter how many times they fall.", "می‌خواهم بگویم رستگاری چیزی نیست که بشود به دستش آورد؛ هدیه‌ای است، به کسانی که می‌خواهند داده می‌شود، به کسانی که تلاش می‌کنند، به کسانی که هرگز متوقف نمی‌شوند، هر چند بار هم که بیفتند."),
            StoryParagraph("I want to tell you that love is not a weakness; love is the strongest thing in the world, stronger than fear, stronger than hatred, stronger than death itself, and that it can survive, as Hassan's love survived, long after the one who loved is gone.", "می‌خواهم بگویم عشق ضعف نیست؛ عشق قوی‌ترین چیز در دنیاست، قوی‌تر از ترس، قوی‌تر از نفرت، قوی‌تر از خود مرگ و می‌تواند زنده بماند، همانطور که عشق حسن زنده ماند، مدت‌ها پس از آنکه عاشق رفته."),
            StoryParagraph("I want to tell you that the ones we lose are never truly lost; they live on in our memories, in our hearts, in the way we treat others, in the way we try to be better, in the way we honor them by becoming, at last, worthy of their love.", "می‌خواهم بگویم کسانی که از دستشان می‌دهیم هرگز واقعاً از دست نمی‌روند؛ در خاطراتمان زنده می‌مانند، در قلب‌هایمان، در شیوه‌ای که با دیگران رفتار می‌کنیم، در شیوه‌ای که تلاش می‌کنیم بهتر باشیم، در شیوه‌ای که با شدن، سرانجام، سزاوار عشقشان، حرمتشان می‌نهیم."),
            StoryParagraph("I want to tell you that I have lived my life in the shadow of that alley, but that I have also lived it in the light of what I learned there; that the alley broke me, but that it also made me; that the boy who failed became the man who tried.", "می‌خواهم بگویم عمرم را در سایه آن کوچه گذرانده‌ام، اما در نور آنچه آنجا آموختم هم گذرانده‌ام؛ که آن کوچه شکستم، اما ساخت هم; که پسر شکست‌خورده، مردی شد که تلاش می‌کند."),
            StoryParagraph("And I want to tell you, most of all, that there is a way to be good again.", "و بیشتر از همه، می‌خواهم بگویم راهی برای دوباره خوب بودن هست."),
            StoryParagraph("That is the thing I have come to believe, the thing I have staked my life on, the thing I would stake my life on again, if I had to; that no matter how far you have fallen, no matter how badly you have failed, no matter how much you have hurt others and yourself, there is still a way to be good again.", "این همان چیزی است که باور کرده‌ام، چیزی که عمرم را بر آن گذاشته‌ام، چیزی که اگر لازم بود، دوباره عمرم را بر آن می‌گذاشتم؛ که هر چقدر هم افتاده باشی، هر چقدر هم بد شکست خورده باشی، هر چقدر هم به دیگران و به خودت آسیب زده باشی، هنوز راهی برای دوباره خوب بودن هست."),
            StoryParagraph("It is not an easy way, and it is not a short way, and it is not a way that can be walked alone; but it exists, and it is waiting, and all you have to do is take the first step, and then the next, and then the next.", "راه آسانی نیست و راه کوتاهی نیست و راهی نیست که تنهایی بتوان پیمودش؛ اما وجود دارد و منتظر است و تنها کاری که باید بکنی این است که اولین قدم را برداری و بعد بعدی و بعد بعدی."),
            StoryParagraph("For I have taken that first step, and I have taken the second, and I have taken many more, and I am still walking, and I will walk, I hope, until the day I die.", "زیرا من آن اولین قدم را برداشته‌ام و دومی را برداشته‌ام و بسیاری بیشتر برداشته‌ام و هنوز راه می‌روم و امیدوارم تا روزی که بمیرم راه بروم."),
            StoryParagraph("Not because I am brave, but because I am afraid; not because I am strong, but because I am weak; not because I am good, but because I want to be good, and because I have learned that wanting to be good is enough to begin.", "نه چون شجاعم، بلکه چون می‌ترسم؛ نه چون قوی‌ام، بلکه چون ضعیفم؛ نه چون خوبم، بلکه چون می‌خواهم خوب باشم و چون آموخته‌ام که خواستن خوب بودن برای شروع کافی است."),
            StoryParagraph("And I want to tell you, before I go, that Hassan was the best man I ever knew, that he was better than me, better than Baba, better than anyone I have ever met, and that the world is worse without him, and that I am worse without him, and that I will spend the rest of my life trying to be worthy of him.", "و می‌خواهم، پیش از رفتن، بگویم حسن بهترین مردی بود که تا حالا شناختم، که از من بهتر بود، از بابا بهتر، از هر کسی که تا حالا ملاقات کرده‌ام بهتر و جهان بدون او بدتر است و من بدون او بدترم و باقی عمرم را صرف تلاش می‌کنم تا سزاوار او باشم."),
            StoryParagraph("I want to tell you that Sohrab is the bravest person I have ever known, that he has suffered more than any child should ever have to suffer, and that he is still standing, still hoping, still, somehow, believing that life is worth living.", "می‌خواهم بگویم سهراب شجاع‌ترین شخصی است که تا حالا شناخته‌ام، که بیش از آنچه هر کودکی باید تحمل کند رنج کشیده و هنوز ایستاده، هنوز امید دارد، هنوز، به نوعی، باور دارد زندگی ارزش زیستن دارد."),
            StoryParagraph("I want to tell you that Soraya is the best thing that ever happened to me, that she saved me when I could not save myself, that she loved me when I could not love myself, that she believed in me when I could not believe in myself.", "می‌خواهم بگویم ثریا بهترین چیزی است که تا حالا برایم اتفاق افتاده، که وقتی نمی‌توانستم خودم را نجات دهم نجاتم داد، که وقتی نمی‌توانستم خودم را دوست بدارم دوستم داشت، که وقتی نمی‌توانستم به خودم باور کنم به من باور داشت."),
            StoryParagraph("I want to tell you that Rahim Khan was the father I needed, that he saw in me something that Baba never saw, that he believed in me even when I did not deserve to be believed in, that he gave me, at the end, the one gift I had always wanted: a way to be good again.", "می‌خواهم بگویم رحیم‌خان پدری بود که نیاز داشتم، که در من چیزی دید که بابا هرگز ندید، که حتی وقتی سزاوار باور داشتن نبودم به من باور داشت، که در پایان، تنها هدیه‌ای را داد که همیشه می‌خواستم: راهی برای دوباره خوب بودن."),
            StoryParagraph("And I want to tell you that I have finally forgiven myself, or that I am trying to, or that I hope to, one day, or that I have stopped expecting to and have started, instead, to live.", "و می‌خواهم بگویم سرانجام خودم را بخشیده‌ام، یا در حال تلاش هستم، یا امیدوارم یک روز، یا از انتظار کشیدن دست کشیده‌ام و به جایش شروع کرده‌ام به زندگی کردن."),
            StoryParagraph("For that, at last, is what the story has taught me: to live, not in the shadow of what was done, but in the light of what might be; to live, not as a prisoner of the past, but as a citizen of the future; to live, not as the boy who failed, but as the man who tries.", "زیرا این، سرانجام، همان چیزی است که داستان به من آموخته: زندگی کردن، نه در سایه آنچه شده، بلکه در نور آنچه می‌تواند شود؛ زندگی کردن، نه همچون زندانی گذشته، بلکه همچون شهروند آینده؛ زندگی کردن، نه همچون پسری که شکست خورد، بلکه همچون مردی که تلاش می‌کند."),
            StoryParagraph("And so I end my story, not with a conclusion, but with a beginning; not with an ending, but with a promise; not with a resolution, but with a hope.", "و اینگونه داستانم را پایان می‌دهم، نه با نتیجه‌گیری، بلکه با آغازی؛ نه با پایانی، بلکه با قولی؛ نه با حل شدنی، بلکه با امیدی."),
            StoryParagraph("The hope that the world can be better; the hope that we can be better; the hope that every alley, no matter how dark, can be walked through, and that on the other side, there is light.", "امید به اینکه جهان می‌تواند بهتر باشد؛ امید به اینکه ما می‌توانیم بهتر باشیم؛ امید به اینکه هر کوچه‌ای، هر چقدر هم تاریک، می‌توان از آن گذشت و در آن سویش، نور هست."),
            StoryParagraph("For that is what Hassan taught me, without ever saying it, in the way he lived his life and in the way he died: that kindness is stronger than cruelty, that loyalty is stronger than betrayal, that love is stronger than hate.", "زیرا این همان چیزی است که حسن به من آموخت، بی‌آنکه هرگز بگویدش، در شیوه‌ای که زندگی کرد و در شیوه‌ای که مرد: که مهربانی از بی‌رحمی قوی‌تر است، که وفاداری از خیانت قوی‌تر است، که عشق از نفرت قوی‌تر است."),
            StoryParagraph("And that is the story I wanted to tell you, the story of a boy who failed and a man who tried, the story of a friendship that was betrayed and a love that was never lost, the story of Afghanistan and of America and of the heart that connects us all.", "و این همان داستانی است که می‌خواستم برایتان بگویم، داستان پسری که شکست خورد و مردی که تلاش کرد، داستان دوستی‌ای که خیانت شد و عشقی که هرگز گم نشد، داستان افغانستان و آمریکا و قلبی که همه ما را به هم می‌بندد."),
            StoryParagraph("For Afghanistan will rise again, as it has risen before; its people will heal, as they have healed before; its beauty will return, as it has returned before; and the kites will fly again over Kabul, as they flew before, in the winters of my childhood.", "زیرا افغانستان دوباره برخیزد، همانطور که قبلاً برخاسته؛ مردمش التیام یابند، همانطور که قبلاً یافته‌اند؛ زیبایی‌اش بازگردد، همانطور که قبلاً بازگشته؛ و بادبادک‌ها دوباره بر فراز کابل پرواز کنند، همانطور که قبلاً پرواز کرده‌اند، در زمستان‌های کودکی من."),
            StoryParagraph("And on that day, I hope to be there; I hope to stand on a hill overlooking the city, with Sohrab beside me, with a kite in my hand, and I hope to look up at the sky, and to see, in the rising kites, everything that was lost and everything that was found, everything that was broken and everything that was healed, everything that was past and everything that is yet to come.", "و در آن روز، امیدوارم آنجا باشم؛ امیدوارم بر تپه‌ای مشرف به شهر بایستم، با سهراب در کنارم، با بادبادکی در دستم و امیدوارم به آسمان نگاه کنم و در بادبادک‌های بالارونده ببینم، هر چیزی که از دست رفت و هر چیزی که یافته شد، هر چیزی که شکست و هر چیزی که التیام یافت، هر چیزی که گذشته است و هر چیزی که هنوز می‌آید."),
            StoryParagraph("And I hope to say, at last, what I have been trying to say my whole life, what Hassan said without words, what Sohrab said without knowing, what the kites have always said, rising against the sky: that there is a way to be good again.", "و امیدوارم سرانجام بگویم آنچه تمام عمر تلاش کرده‌ام بگویم، آنچه حسن بی‌کلمات گفت، آنچه سهراب بی‌آنکه بداند گفت، آنچه بادبادک‌ها همیشه گفتند، در حال بالا رفتن در آسمان: که راهی برای دوباره خوب بودن هست."),
            StoryParagraph("And so I end where I began, in Kabul, in the winter, with a kite and a boy and a promise; but I end also with something I did not have when I began: with hope.", "و اینگونه همان‌جا پایان می‌دهم که آغاز کردم، در کابل، در زمستان، با بادبادکی و پسری و قولی؛ اما همچنین با چیزی پایان می‌دهم که وقتی شروع کردم نداشتم: با امید."),
            StoryParagraph("For the boy I was has grown into the man I am, and the man I am is not the man I feared I would be; he is the man I hoped I could be, the man who tries, the man who fails and tries again, the man who has learned, at last, to be good.", "زیرا پسری که بودم به مردی که هستم رشد کرده و مردی که هستم همان مردی نیست که می‌ترسیدم باشم؛ همان مردی است که امید داشتم باشم، مردی که تلاش می‌کند، مردی که شکست می‌خورد و دوباره تلاش می‌کند، مردی که سرانجام، آموخته خوب باشد."),
            StoryParagraph("And that is enough; that has always been enough; that is, at last, all I need.", "و این کافی است؛ همیشه کافی بوده؛ این، سرانجام، تمام چیزی است که نیاز دارم."),
            StoryParagraph("The end.", "پایان."),
            StoryParagraph("But the story, I hope, goes on — in you, the reader, who now hold it; in the lives you will live, the good you will do, the ways you will be good again.", "اما داستان، امیدوارم، ادامه یابد — در تو، خواننده، که حالا آن را در دست داری؛ در زندگی‌هایی که زندگی می‌کنی، خیری که می‌کنی، شیوه‌هایی که دوباره خوب می‌شوی.")
        )
    )
}